}
def slots_for(N): return {i:(2**40+13*i) for i in range(N)}
def sim_linear(main,S,N,back=False):
    slots=[None]*S
    for i in range(N):
        mp=main(i,S)%S
        step=1
        while slots[mp] is not None:
            mp=(mp-step)%S if back else (mp+1)%S
            step+=1
        slots[mp]=i
    order=[]
    for s in range(S):
        if slots[s] is not None: order.append(slots[s])
    return order
def sim_chain(main,S,N):
    slots=[None]*S; nxt=[None]*S; lf=S-1
    for i in range(N):
        mp=main(i,S)%S
        if slots[mp] is None: slots[mp]=i
        else:
            # colliding key in its main position?
            other=slots[mp]
            if main(other,S)%S==mp:
                # find free from top
                f=lf
                while f>=0 and slots[f] is not None: f-=1
                if f<0: return None
                lf=f-1
                slots[f]=i
                p=mp
                while nxt[p] is not None: p=nxt[p]
