                while f>=0 and slots[f] is not None: f-=1
                if f<0: return None
                lf=f-1
                slots[f]=other; nxt[f]=nxt[mp]
                slots[mp]=i; nxt[mp]=None
    order=[]
    for s in range(S):
        if slots[s] is not None: order.append(slots[s])
