} CallSite;

struct Proto {
  GCObject *next;
  unsigned char tt;
  unsigned char marked;
  int numparams;
  int is_vararg;
  int maxstacksize;
  int sizecode;
  int sizek;
  int sizep;
  int sizeupvalues;
  int sizelocvars;
  int linedefined;
  int lastlinedefined;
  Instruction *code;
  TValue *k;
  struct Proto **p;
  Upvaldesc *upvalues;
  LocVar *locvars;
  CallSite *callsites;
  int *lineinfo;
  struct TString *source;
};

typedef union Node {
  struct {
    TValue key;
    TValue val;
    struct Node *next;
  } u;
  TValue value;
} Node;

struct Table {
  GCObject *next;
  unsigned char tt;
  unsigned char marked;
  unsigned char flags;
  lua_Integer alimit;
  struct Table *metatable;
  TValue *array;
  Node *node;
  unsigned int sizearray;
  unsigned int lsizenode;
  Node *lastfree;
};

