#define TM_CACHEMASK    0x1f
#define TM_CACHEVALID   0x40
#define cachevalid(t)   ((t)->flags & TM_CACHEVALID)
#define cachev(t,f)     ((t)->flags |= TM_CACHEVALID | (f))
#define cachereset(t)   ((t)->flags = 0)

typedef struct lua_Debug {
  struct lua_State *L1;
  int currentline;
  int linedefined;
  int lastlinedefined;
  int nups;
  int nparams;
  int isvararg;
  int istailcall;
  int extraargs;
  int ftransfer;
  int ntransfer;
  int event;
  int short_srclen;
  const char *short_src;
  int srclen;
  const char *source;
  const char *what;
  const char *name;
  const char *namewhat;
  int i_ci;
} lua_Debug;

typedef void (*lua_Hook) (struct lua_State *L, lua_Debug *ar);

typedef struct lua_State lua_State;

typedef struct luaL_Buffer {
  lua_State *L;
  char *p;
  size_t size;
  char buf[1024];
  size_t lvl;
} luaL_Buffer;

/* limits */
#define MAXSTACK        1000000
#define LUAI_MAXCCALLS  200
#define MAXUPVAL        255
#define MAXVARS         200
#define MAXARG_Bx       ((1 << 16) - 1)
#define MAXARG_sBx      (MAXARG_Bx >> 1)
#define LUAI_MAXSHORTLEN 40

#endif
