#ifndef LSTATE_H
#define LSTATE_H

#include "lua.h"
#include "lobject.h"
#include <setjmp.h>
#include <stdarg.h>

#define LUA_MINSTACK      20
#define LUA_MAXSTACK      1000000
#define CIST_C            (1<<0)
#define CIST_LUA          (1<<1)
#define CIST_FRESH        (1<<2)
#define CIST_HOOKED       (1<<3)
#define CIST_YPCALL       (1<<4)
#define CIST_TAIL         (1<<5)
#define CIST_HOOKYIELD    (1<<6)
#define CIST_TRAN         (1<<7)
#define CIST_YIELDED      (1<<8)
#define CIST_CCCLOSURE    (1<<9)

typedef struct lua_longjmp {
  struct lua_longjmp *previous;
  jmp_buf b;
  volatile int status;
} lua_longjmp;

typedef struct CallInfo {
  int func;         /* stack offset of the function */
  int top;          /* stack offset of the frame top */
  int nresults;
  int callstatus;
  int nextra;       /* number of extra (vararg) arguments for Lua frames */
  int varargbase;   /* stack offset where varargs start */
  int extraargs;    /* number of extra args passed to C functions */
  int ftransfer;    /* transfer information for resume/yield */
  int ntransfer;
  int funcidx;      /* registry index for C functions (for debug names) */
  int tailcall;     /* 1 if this is a tail call */
  union {
    struct {
      struct Proto *p;
      int savedpc;
    } l;
    struct {
      lua_CFunction f;
      lua_CFunctionK k;
      lua_Integer ctx;
    } c;
  } u;
} CallInfo;

typedef struct TString TString;
typedef struct UpVal UpVal;
typedef struct Table Table;
typedef struct Proto Proto;
typedef struct Closure Closure;
typedef struct Udata Udata;

typedef void *(*lua_Alloc) (void *ud, void *ptr, size_t osize, size_t nsize);

typedef struct global_State {
  lua_Alloc alloc;
  void *ud;
  lua_State *mainthread;
  TValue l_registry;
  GCObject *allgc;       /* list of all collectable objects */
  GCObject *fixed;       /* list of objects to never collect */
  GCObject *tobefnz;
  TString **strt;
  lu_uint sizestrt;
  lu_uint struse;
  unsigned int seed;
  lu_byte gcstopem;      /* stop emergency collection */
  lu_byte gcstate;
  lu_byte gcrunning;
  lu_byte gcemergency;
  size_t GCdebt;         /* memory allocated since last collection */
  size_t GCthreshold;
  size_t totalbytes;
  lu_byte gcstopcount;
  lua_WarnFunction warnf;   /* warning function */
  void *warnud;
  lua_Hook hook;   /* per global? no, per thread */
} global_State;

typedef struct CallBase {
  CallInfo base_ci;
  int dummy;
} CallBase;

struct lua_State {
  GCObject *next;      /* chain in GC list */
  unsigned char tt;    /* LUA_VTHREAD */
  unsigned char marked;
  global_State *l_G;
  CallInfo *ci;        /* current CallInfo */
  CallInfo *base_ci;   /* bottom CallInfo */
  TValue *stack;
  int stack_last;      /* size of stack */
  int top;             /* stack offset of top */
  int stacksize;
  int status;
  int nCcalls;         /* number of nested (C) calls */
  int nCcalldepth;
  UpVal *openupval;    /* list of open upvalues */
  lua_longjmp *errorJmp;
  CallInfo ci_array[1];  /* not used; dynamic */
  int hookmask;
  lua_Hook hook;
  lua_Integer hookcount;
  lua_Integer hookL;
  int allowhook;
  int errfunc;         /* stack offset of error function, 0 if none */
  int errfuncidx;
  unsigned char gcstopped;
  unsigned char closed;
  /* stack of CallInfos */
  CallInfo *cis;
  int ci_size;
  int ci_nci;
  lua_State *prevthread;  /* not used */
};

/* access to global state */
#define G(L)  ((L)->l_G)

/* registry indices */
#define LUA_RIDX_MAINTHREAD  1
#define LUA_RIDX_GLOBALS     2
#define LUA_RIDX_LAST        2

/* upvalue "open" test */
#define isupvalue(v)  (upisopen(v))

/* CallInfo helpers */
#define ci_func(ci)     (s2v((L)->stack + (ci)->func))
#define ci_p(ci)        ((ci)->u.l.p)
#define isLua(ci)       (!((ci)->callstatus & CIST_C))
#define isLuaCfunction(ci) ((ci)->callstatus & CIST_C)
#define isLuaThread(ci) (isLua(ci) && !(ci)->callstatus & CIST_TAIL)

#define s2v(o)  (o)

/* error handling */
l_noret luaD_throw (lua_State *L, int errcode);
int luaD_pcall (lua_State *L, void (*f) (lua_State *L, void *ud), void *ud,
