void luaD_freethread (lua_State *L, lua_State *L1);
void luaD_closeprotected (lua_State *L, int level, int status);
void luaD_seterrorobj (lua_State *L, int errcode, TValue *oldval);
void luaD_setfuncs (lua_State *L, const luaL_Reg *l, int nup);
int lua_status (lua_State *L);

