      break;
    }
    case LUA_TFUNCTION: {
      Closure *cl = (Closure *)o;
      int i;
      for (i = 0; i < cl->nupvalues; i++)
        markvalue(L, &cl->upvals[i]->value);
      if (!cl->isC) {
        Proto *p = cl->f.p;
        markobj(L, (GCObject *)p);
      }
      break;
    }
    case LUA_TUSERDATA: {
      Udata *u = (Udata *)o;
      if (u->metatable) markobj(L, (GCObject *)u->metatable);
      if (u->env) markobj(L, (GCObject *)u->env);
      break;
    }
    case LUA_TTHREAD: {
      lua_State *L1 = (lua_State *)o;
      CallInfo *ci;
      TValue *top;
      for (ci = L1->base_ci; ci != NULL; ci = ci->prev) {
        if (ci->func >= 0 && ci->func < L1->top) {
          int i;
          for (i = ci->func; i < ci->top && i < L1->top; i++)
            markvalue(L, &L1->stack[i]);
        }
      }
      top = L1->stack + L1->top;
      {
        TValue *p;
        for (p = L1->stack; p < top; p++)
          markvalue(L, p);
      }
      break;
    }
    case LUA_TPROTO: {
      Proto *p = (Proto *)o;
      int i;
      if (p->source) markobj(L, (GCObject *)p->source);
      for (i = 0; i < p->sizek; i++) markvalue(L, &p->k[i]);
      for (i = 0; i < p->sizep; i++) markobj(L, (GCObject *)p->p[i]);
      for (i = 0; i < p->sizelocvars; i++)
        if (p->locvars[i].varname) markobj(L, (GCObject *)p->locvars[i].varname);
      for (i = 0; i < p->sizeupvalues; i++)
        if (p->upvalues[i].name) markobj(L, (GCObject *)p->upvalues[i].name);
      if (p->callsites) {
