static void markall (lua_State *L) {
  global_State *g = G(L);
  GCObject *o;
  /* clear marks */
  for (o = g->allgc; o != NULL; o = o->next) o->marked = 0;
  for (o = g->fixed; o != NULL; o = o->next) o->marked = 0;
  /* mark fixed objects */
  for (o = g->fixed; o != NULL; o = o->next) markobj(L, o);
  /* mark registry */
  markvalue(L, &g->l_registry);
  /* mark all threads in the main chain */
  {
    lua_State *th;
    for (th = g->mainthread; th != NULL; th = th->nextthread)
      if (!th->closed) markobj(L, (GCObject *)th);
  }
}

static void listremove (GCObject **list, GCObject *o) {
  GCObject **p = list;
  while (*p != NULL) {
    if (*p == o) { *p = o->next; return; }
    p = &(*p)->next;
  }
}

static int isfinalizable (lua_State *L, GCObject *o) {
  switch (o->tt) {
    case LUA_VUSERDATA: {
      Udata *u = (Udata *)o;
      if (u->metatable != NULL) {
        TValue v;
        if (luaH_getshortstr(u->metatable, "__gc", &v) && !ttisnil(&v))
          return 1;
      }
      return 0;
    }
    case LUA_VTABLE: {
      Table *t = (Table *)o;
      if (t->metatable != NULL) {
        TValue v;
        if (luaH_getshortstr(t->metatable, "__gc", &v) && !ttisnil(&v))
          return 1;
      }
      return 0;
    }
    default: return 0;
  }
}

static GCObject *finlist = NULL;

static void sweep (lua_State *L) {
  global_State *g = G(L);
  GCObject **p = &g->allgc;
  int collected = 0;
  while (*p != NULL) {
    GCObject *o = *p;
    if (o->marked) {
      p = &o->next;
      continue;
    }
    if (isfinalizable(L, o)) {
      /* keep it alive for finalization */
      o->marked = 1;
      o->next = finlist;
      finlist = o;
      *p = o->next;
      o->next = NULL;
      /* relink later */
      collected++;
      continue;
    }
    /* remove from string table if needed */
    if (ttisshrstring_(o) || (o->tt & 0x0f) == LUA_TSTRING)
      luaS_remove(L, (TString *)o);
    else if (o->tt == LUA_VTHREAD) {
      lua_State *L1 = (lua_State *)o;
      /* remove from thread chain */
      listremove_(&g->mainthread, o);
      luaM_free(L, L1->stack, sizeof(TValue) * L1->stacksize);
      luaM_free(L, L1->cis, sizeof(CallInfo) * L1->ci_size);
      luaM_free(L, o, sizeof(lua_State));
      continue;
    }
    else if (o->tt == LUA_VUPVAL)
      luaM_free(L, o, sizeof(UpVal));
    else if (o->tt == LUA_VPROTO) {
      Proto *pr = (Proto *)o;
      if (pr->code) luaM_free(L, pr->code, sizeof(Instruction)*pr->sizecode);
      if (pr->k) luaM_free(L, pr->k, sizeof(TValue)*pr->sizek);
      if (pr->p) luaM_free(L, pr->p, sizeof(Proto*)*pr->sizep);
      if (pr->upvalues) luaM_free(L, pr->upvalues, sizeof(Upvaldesc)*pr->sizeupvalues);
      if (pr->locvars) luaM_free(L, pr->locvars, sizeof(LocVar)*pr->sizelocvars);
      if (pr->callsites) luaM_free(L, pr->callsites, sizeof(CallSite)*pr->sizecode);
      if (pr->lineinfo) luaM_free(L, pr->lineinfo, sizeof(int)*pr->sizecode);
      luaM_free(L, o, sizeof(Proto));
      continue;
    }
    else if (o->tt == LUA_VTABLE) {
