#define CIST_HOOKED       (1<<3)
#define CIST_YPCALL       (1<<4)
#define CIST_TAIL         (1<<5)
#define CIST_HOOKYIELD    (1<<6)
#define CIST_YIELDED      (1<<7)

typedef struct lua_longjmp {
  struct lua_longjmp *previous;
  jmp_buf b;
  volatile int status;
} lua_longjmp;

typedef struct CallInfo {
  struct CallInfo *prev;   /* previous CallInfo (caller) */
  struct CallInfo *next;   /* next CallInfo (callee) */
  int func;         /* stack offset of the function */
  int top;          /* stack offset of the frame top */
  int nresults;
