from fractions import Fraction as F
M64=1<<64
B=2**40
def solve(order, N, m):
    lo=F(0); hi=F(M64)
    slot={}
    for p,i in enumerate(order): slot[i]=p
    for i in range(N):
        k=B+13*i; s=slot[i]
        a=F(s*M64, k<<m); b=F((s+1)*M64, k<<m)
        lo=max(lo,a); hi=min(hi,b)
    return (lo,hi) if lo<hi else None
