    r=solve(order16,16,m)
    if r: print("m=",m,"K in",float(r[0]),float(r[1]), "approx int:", int(r[0]) if r[0]<2**63 else None)
    else: print("m=",m,"none")
# also for a model slot = (key*K) mod 2^m (low bits)
def solve_low(order,N,m):
    # need (key*K) mod 2^m == slot[i] exactly
    sols=[]
    for c in range(1,1<<m,2):
        ok=True
        slot={}
        for p,i in enumerate(order): slot[i]=p
        for i in range(N):
            k=B+13*i
            if (k*c)%(1<<m)!=slot[i]% (1<<m): ok=False;break
        if ok: sols.append(c)
    return sols
for m in range(3,12):
    print("low m=",m, solve_low(order16,16,m)[:5])
