cat > lstring.c <<'EOF'
/* string interning */
#include "lstring.h"
#include "lmem.h"
#include "lgc.h"
#include "lstate.h"
#include "ldebug.h"
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

static const char _digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";

unsigned int luaS_hash (const char *str, size_t l, unsigned int seed) {
  unsigned int h = seed ^ (unsigned int)l;
  for (; l > 0; l--)
    h ^= ((h << 5) + (h >> 2) + (unsigned char)str[l - 1]);
  return h;
}

unsigned int luaS_hashint (lua_Integer i) {
  /* deterministic hash for integer keys */
  lua_uint h = (lua_uint)(unsigned long long)i;
  h ^= h >> 15;
  h *= 0x2c1b3c6du;
  h ^= h >> 12;
  h *= 0x297a2d39u;
  h ^= h >> 15;
  return h;
}

unsigned int luaS_hashflt (lua_State *L, lua_Number n) {
  /* hash for floats: use the string representation of the fractional part */
  char buf[64];
  int len;
  len = snprintf(buf, sizeof(buf), "%.14a", (double)n);
  if (len <= 0) { buf[0] = '\0'; len = 0; }
  return luaS_hash(buf, (size_t)len, G(L)->seed);
}

void luaS_init (lua_State *L) {
  luaS_resize(L, 32);
}

void luaS_resize (lua_State *L, int newsize) {
  global_State *g = G(L);
  TString **newhash;
  int i;
  if (newsize < 1) newsize = 1;
  newhash = (TString **)luaM_newvector_(L, newsize, TString *);
  for (i = 0; i < newsize; i++) newhash[i] = NULL;
  /* rehash */
  for (i = 0; i < (int)g->sizestrt; i++) {
    TString *ts = g->strt[i];
    while (ts != NULL) {
      TString *hnext = ts->hnext;
      unsigned int h = lmod(ts->hash, newsize);
      ts->hnext = newhash[h];
      newhash[h] = ts;
      ts = hnext;
    }
  }
  if (g->strt != NULL) luaM_free(L, g->strt, sizeof(TString *) * g->sizestrt);
  g->strt = newhash;
  g->sizestrt = newsize;
}

TString *luaS_createlong (lua_State *L, const char *str, size_t l) {
  TString *ts;
  size_t totalsize = sizeof(TString) + l + 1;
  ts = (TString *)luaM_alloc_(L, NULL, 0, totalsize);
  ts->next = NULL; ts->hnext = NULL; ts->length = l;
  ts->hash = 0;
  ts->tt = LUA_VLNGSTR; ts->marked = 0;
  memcpy(ts->contents, str, l * sizeof(char));
  ts->contents[l] = '\0';
  return ts;
}

TString *luaS_newlstr (lua_State *L, const char *str, size_t l) {
  global_State *g = G(L);
  TString *ts;
  unsigned int h;
  if (l == 0) str = "";
  h = luaS_hash(str, l, g->seed);
  ts = g->strt[lmod(h, g->sizestrt)];
  while (ts != NULL) {
    if (ts->length == l && memcmp(ts->contents, str, l) == 0)
      return ts;
    ts = ts->hnext;
  }
  if (g->struse >= g->sizestrt && g->sizestrt < (1u << 26))
    luaS_resize(L, (int)(g->sizestrt * 2));
  {
    size_t totalsize = sizeof(TString) + l + 1;
    ts = (TString *)luaM_alloc_(L, NULL, 0, totalsize);
    ts->next = NULL; ts->hnext = NULL; ts->length = l;
    ts->hash = h;
    ts->tt = LUA_VSHRSTR; ts->marked = 1;
    memcpy(ts->contents, str, l * sizeof(char));
    ts->contents[l] = '\0';
    ts->hnext = g->strt[lmod(h, g->sizestrt)];
    g->strt[lmod(h, g->sizestrt)] = ts;
    g->struse++;
  }
  return ts;
}

TString *luaS_new (lua_State *L, const char *str) {
  return luaS_newlstr(L, str, strlen(str));
}

TString *luaS_fixstr (lua_State *L, const char *str, size_t l) {
  TString *ts = luaS_newlstr(L, str, l);
  luaC_fix(L, (GCObject *)ts);
  return ts;
}

void luaS_remove (lua_State *L, TString *ts) {
  global_State *g = G(L);
  TString **p;
  if (ts->tt != LUA_VSHRSTR) return;
  p = &g->strt[lmod(ts->hash, g->sizestrt)];
  while (*p != ts) {
    if (*p == NULL) return;
    p = &(*p)->hnext;
  }
  *p = ts->hnext;
  g->struse--;
  luaM_free(L, ts, sizeof(TString) + ts->length + 1);
}
