#include "ltable.h"
#include "lobject.h"
#include "lstate.h"
#include "lstring.h"
#include "lmem.h"
#include "lgc.h"
#include "lvm.h"
#include "ldebug.h"
#include <string.h>
#include <stdlib.h>

#define dummynode  NULL
#define isdummy(t)  ((t)->node == NULL)
#define sizenode(t) (isdummy(t) ? 0u : (1u << (t)->lsizenode))

static const TValue nilobject_ = { LUA_VNIL, { 0 } };

/*
** Node access
*/
#define gval(n)      (&(n)->u.val)
#define gkey(n)      (&(n)->u.key)
#define gnext(n)     ((n)->u.next)
#define gnode(t,i)   (&(t)->node[i])
#define keyisnil(n)  (ttisnil(gkey(n)))
#define valisnil(n)  (ttisnil(gval(n)))
#define keyisempty(n) (ttisnil(gkey(n)) && ttisnil(gval(n)))

/*
** 'luaH_realasize' returns the real size of the array part
*/
unsigned int luaH_realasize (const Table *t) {
  return t->sizearray;
}

/*
** returns the index of the node in the table
*/
static unsigned int nodeindex (Table *t, Node *n) {
  return cast_uint(n - t->node);
}

/*
** hash functions
*/
static unsigned int hashint (lua_Integer i) {
  unsigned int h = cast_uint(l_castS2U(i));
  h ^= h >> 15;
  h *= 0x2c1b3c6du;
  h ^= h >> 12;
  h *= 0x297a2d39u;
  h ^= h >> 15;
  return h;
}

static unsigned int hashpointer (const void *p) {
  unsigned long long h = (unsigned long long)(size_t)p;
  h ^= h >> 29;
  h *= 0x2c1b3c6dULL;
  h ^= h >> 17;
  return cast_uint(h);
}

Node *luaH_mainposition (const Table *t, const TValue *key) {
  unsigned int mask = (sizenode(t) - 1) & 0x7fffffff;
  switch (key->tt) {
    case LUA_VNUMINT:
      return gnode(t, lmod(hashint(ivalue(key)), sizenode(t)));
    case LUA_VNUMFLT:
      return gnode(t, lmod(hashfloat_(L, fltvalue(key)), sizenode(t)));
    case LUA_VSHRSTR:
    case LUA_VLNGSTR:
      return gnode(t, lmod(tsvalue(key)->hash, sizenode(t)));
    case LUA_TLIGHTUSERDATA:
      return gnode(t, lmod(hashpointer(pvalue(key)), sizenode(t)));
    default:
      return gnode(t, lmod(hashpointer(gcvalue(key)), sizenode(t)));
  }
}

/*
** returns the main position of an integer key
*/
static Node *mainposition_int (Table *t, lua_Integer key) {
  return gnode(t, lmod(hashint(key), sizenode(t)));
}

static Node *getnode (Table *t, lua_Integer key) {
  if (isdummy(t)) return NULL;
  return mainposition_int(t, key);
}

/*
** 't' is a table; find the node for integer key
*/
static const TValue *getint (Table *t, lua_Integer key) {
  if (l_castS2U(key) - 1u < t->sizearray)
    return &t->array[key - 1];
  else {
    Node *n;
    if (isdummy(t)) return &nilobject_;
    n = mainposition_int(t, key);
    for (;;) {
      if (keyisempty(n))
        return &nilobject_;
      else if (ttisinteger(gkey(n)) && ivalue(gkey(n)) == key)
        return gval(n);
      else n = gnext(n);
    }
  }
}

const TValue *luaH_getint (Table *t, lua_Integer key) {
  return getint(t, key);
}

static const TValue *getstrnode (Table *t, TString *key) {
  Node *n;
  if (isdummy(t)) return &nilobject_;
  n = gnode(t, lmod(key->hash, sizenode(t)));
  for (;;) {
    if (keyisempty(n)) return &nilobject_;
    if (ttisstring(gkey(n)) && tsvalue(gkey(n)) == key)
      return gval(n);
    n = gnext(n);
  }
}

const TValue *luaH_getstr (Table *t, TString *key) {
  return getstrnode(t, key);
}

const TValue *luaH_getshortstr (Table *t, const char *str, TValue *out) {
  /* for short interned strings: hash computed on the fly */
  Node *n;
  unsigned int h;
  if (isdummy(t)) return &nilobject_;
  h = luaS_hashlite(str);
  n = gnode(t, lmod(h, sizenode(t)));
  for (;;) {
    if (keyisempty(n)) return &nilobject_;
    if (ttisstring(gkey(n)) && tsvalue(gkey(n))->length == strlen(str) &&
        memcmp(tsvalue(gkey(n))->contents, str, strlen(str)) == 0)
      return gval(n);
    n = gnext(n);
  }
}

