static void countint (lua_Integer key, size_t *nums) {
  unsigned int k = cast_uint(key);
  if (k <= MAXASIZE) {
    int lg = 0;
    unsigned int v = k;
    /* find lg such that 2^lg <= k < 2^(lg+1); nums[lg] counts keys in [2^(lg-1)+1, 2^lg] */
    if (k <= 1) lg = 0;
    else {
      lg = 0;
      while ((1u << (lg + 1)) <= k) lg++;
      /* nums[lg] counts keys in [2^(lg-1)+1, 2^lg] */
    }
    nums[lg]++;
  }
}

