  size_t lg, ttlg;
  size_t ause = 0;
  size_t i = 1;
  for (lg = 0, ttlg = 0; lg <= MAXABITS; lg++) {
    size_t lc = 1u << lg;
    size_t ttlc = ttlg + lc;
    size_t lim = (ttlc < t->sizearray) ? ttlc : t->sizearray;
    size_t j;
    if (lim < i) break;
    for (j = i; j <= lim; j++) {
      if (!ttisnil(&t->array[j - 1])) {
        ause++;
        nums[lg]++;
      }
    }
    ttlg = ttlc;
    i = lim + 1;
    if (i > t->sizearray) break;
  }
  return ause;
}

