  size_t totaluse = 0;
  for (i = 0; i < sizen; i++) {
    Node *n = gnode(t, i);
    if (!valisnil(n)) {
      totaluse++;
      if (ttisinteger(gkey(n))) countint(ivalue(gkey(n)), nums);
    }
  }
  *pnodesize = sizen;
  return totaluse;
}

static unsigned int ceillog2 (unsigned int x) {
  unsigned int l = 0;
  if (x == 0) return 0;
  x--;
  while (x > 0) { x >>= 1; l++; }
  return l;
}

static size_t computesizes (size_t nums[], size_t *pna) {
  int i;
  size_t totaluse = 0;
  size_t a = 0;
  size_t asize = 0;
  for (i = 0; i <= MAXABITS; i++) {
    totaluse += nums[i];
    a += nums[i];
    if (a > ((size_t)1 << i) / 2)
      asize = ((size_t)1 << i);
