static lua_Integer hash_search (Table *t, lua_Integer j) {
  lua_Integer i;
  i = j;
  for (;;) {
    lua_Integer nj = j * 2;
    if (nj > (lua_Integer)MAXASIZE) nj = (lua_Integer)MAXASIZE;
    if (nj == j || ttisnil(getint(t, nj))) break;
