      if (gnext(n) == mp)  /* avoid self reference */
        gnext(n) = NULL;
    }
    else {  /* new node goes into a free position, chained */
      gnext(n) = gnext(mp);
      gnext(mp) = n;
      mp = n;
    }
  }
  mp->u.key = *key;
  mp->u.val = *value;
}

/* --------------------------------------------------------------- rehash -- */

static void countint (lua_Integer key, size_t *nums) {
  unsigned int k = cast_uint(key);
  if (k <= MAXASIZE) {
    int lg = 0;
    unsigned int v = k;
    /* find lg such that 2^lg <= k < 2^(lg+1); nums[lg] counts keys in [2^(lg-1)+1, 2^lg] */
    if (k <= 1) lg = 0;
    else {
      lg = 0;
      while ((1u << (lg + 1)) <= k) lg++;
      /* nums[lg] counts keys in [2^(lg-1)+1, 2^lg] */
    }
    nums[lg]++;
  }
}

static size_t numusearray (const Table *t, size_t *nums) {
  size_t lg, ttlg;
  size_t ause = 0;
  size_t i = 1;
  for (lg = 0, ttlg = 0; lg <= MAXABITS; lg++) {
    size_t lc = 1u << lg;
    size_t ttlc = ttlg + lc;
    size_t lim = (ttlc < t->sizearray) ? ttlc : t->sizearray;
    size_t j;
    if (lim < i) break;
    for (j = i; j <= lim; j++) {
      if (!ttisnil(&t->array[j - 1])) {
        ause++;
        nums[lg]++;
      }
    }
    ttlg = ttlc;
    i = lim + 1;
    if (i > t->sizearray) break;
  }
  return ause;
}

static size_t numusehash (const Table *t, size_t *nums, size_t *pnodesize) {
  unsigned int i, sizen = sizenode(t);
  size_t totaluse = 0;
  for (i = 0; i < sizen; i++) {
    Node *n = gnode(t, i);
    if (!valisnil(n)) {
      totaluse++;
      if (ttisinteger(gkey(n))) countint(ivalue(gkey(n)), nums);
    }
  }
  *pnodesize = sizen;
  return totaluse;
}

static unsigned int ceillog2 (unsigned int x) {
  unsigned int l = 0;
  if (x == 0) return 0;
  x--;
  while (x > 0) { x >>= 1; l++; }
  return l;
}

static size_t computesizes (size_t nums[], size_t *pna) {
  int i;
  size_t totaluse = 0;
  size_t a = 0;
  size_t asize = 0;
  for (i = 0; i <= MAXABITS; i++) {
    totaluse += nums[i];
    a += nums[i];
    if (a > ((size_t)1 << i) / 2)
      asize = ((size_t)1 << i);
  }
  *pna = a;
  return asize;
}

void luaH_resize (lua_State *L, Table *t, unsigned int newasize, unsigned int nhsize) {
  TValue *newarray;
  Node *newnode;
  unsigned int oldasize = t->sizearray;
  unsigned int oldsizen = sizenode(t);
  unsigned int i;
  unsigned int olsize = t->lsizenode;
  TValue *oldarray = t->array;
  Node *oldnode = t->node;
  /* allocate new parts */
  newasize = (newasize > MAXASIZE) ? MAXASIZE : newasize;
  if (nhsize == 0) nhsize = 1;
  newnode = (Node *)luaM_newvector_(L, nhsize, Node);
  for (i = 0; i < nhsize; i++) {
    setnilvalue(&newnode[i].u.key);
    setnilvalue(&newnode[i].u.val);
    newnode[i].u.next = NULL;
  }
  if (newasize > 0) {
    newarray = (TValue *)luaM_newvector_(L, newasize, TValue);
    for (i = 0; i < newasize; i++) setnilvalue(&newarray[i]);
  }
  else newarray = NULL;
