    {
      Node *n = luaH_mainposition(t, key);
      for (;;) {
        if (luaV_rawequalobj(gkey(n), key)) return gval(n);
        n = gnext(n);
        if (n == NULL) break;
      }
    }
    return (TValue *)&nilobject_;
  }
