/* ------------------------------------------------------------------ next -- */

static unsigned int arrayindex (const TValue *key, unsigned int asize) {
  if (ttisinteger(key)) {
    lua_Integer k = ivalue(key);
    if (l_castS2U(k) - 1u < asize) return cast_uint(k);
  }
  return 0;
}

static unsigned int findindex (lua_State *L, Table *t, TValue *key, unsigned int asize) {
  unsigned int i;
  if (ttisnil(key)) return 0;
  i = arrayindex(key, asize);
  if (i > 0) return i;
  {
    Node *n = luaH_mainposition(t, key);
    for (;;) {
      if (keyisempty(n))
        luaG_runerror(L, "invalid key to 'next'");
      if (luaV_rawequalobj(gkey(n), key))
        return nodeindex(t, n) + asize + 1;
      n = gnext(n);
      if (n == NULL) break;
    }
    luaG_runerror(L, "invalid key to 'next'");
    return 0;
  }
}

int luaH_next (lua_State *L, Table *t, TValue *key) {
  unsigned int asize = t->sizearray;
  unsigned int i = findindex(L, t, key, asize);
  for (; i < asize; i++) {
    if (!ttisnil(&t->array[i])) {
      setivalue(key, (lua_Integer)(i + 1));
      setobj2s(key + 1, &t->array[i]);
      return 1;
    }
  }
  i -= asize;
  {
    unsigned int sn = sizenode(t);
    for (; i < sn; i++) {
      Node *n = gnode(t, i);
      if (!valisnil(n)) {
        setobj2s(key, gkey(n));
        setobj2s(key + 1, gval(n));
        return 1;
      }
    }
  }
  return 0;
}

/* ---------------------------------------------------------------- getn ---- */

static lua_Integer hash_search (Table *t, lua_Integer j) {
  lua_Integer i;
  i = j;
  for (;;) {
    lua_Integer nj = j * 2;
    if (nj > (lua_Integer)MAXASIZE) nj = (lua_Integer)MAXASIZE;
    if (nj == j || ttisnil(getint(t, nj))) break;
    i = j;
    j = nj;
  }
  while (j - i > 1) {
    lua_Integer m = (i + j) / 2;
    if (ttisnil(getint(t, m))) j = m;
    else i = m;
  }
  return i;
}

lua_Integer luaH_getn (lua_State *L, Table *t) {
  unsigned int asize = t->sizearray;
  if (asize > 0 && ttisnil(&t->array[asize - 1])) {
    lua_Integer i = 0, j = asize;
    while (j - i > 1) {
      lua_Integer m = (i + j) / 2;
      if (ttisnil(&t->array[m - 1])) j = m;
      else i = m;
    }
    return i;
  }
  else {
    if (asize > 0) {
      if (ttisnil(getint(t, asize + 1))) return asize;
      return hash_search(t, asize + 1);
    }
    else {
      if (ttisnil(getint(t, 1))) return 0;
      return hash_search(t, 1);
    }
  }
}

void luaH_resizearray (lua_State *L, Table *t, unsigned int newasize) {
  luaH_resize(L, t, newasize, sizenode(t));
}
