unsigned int luaH_hashfloat (lua_Number n) {
  union { lua_Number n; unsigned long long u; } u;
  u.n = n;
  if (u.u == 0) return 0;
  return cast_uint(u.u * 2654435761u);
}

Node *luaH_mainposition (const Table *t, const TValue *key) {
  unsigned int sz = sizenode(t);
