    case LUA_VNUMFLT: h = luaH_hashfloat(fltvalue(key)); break;
    case LUA_VSHRSTR: case LUA_VLNGSTR: h = tsvalue(key)->hash; break;
    case LUA_TLIGHTUSERDATA: h = hashpointer(pvalue(key)); break;
