static Node *getfreepos (Table *t) {
  Node *n = t->lastfree;
  if (n == NULL) return NULL;
  while (n >= t->node) {
    if (keyisempty(n)) {
      t->lastfree = (n == t->node) ? NULL : n - 1;
      return n;
    }
    n--;
