      while (gnext(othern) != mp) othern = gnext(othern);
      gnext(othern) = n;
      *n = *mp;
      if (gnext(n) == mp) gnext(n) = NULL;
      mp->u.key = *key;
      mp->u.val = *value;
      return;
    }
    else {
      gnext(n) = gnext(mp);
      gnext(mp) = n;
      mp = n;
