static unsigned int arrayindex (const TValue *key, unsigned int asize) {
  if (ttisinteger(key)) {
    lua_Integer k = ivalue(key);
    if (l_castS2U(k) - 1u < asize) return cast_uint(k);
  }
  return 0;
}

static unsigned int findindex (lua_State *L, Table *t, TValue *key, unsigned int asize) {
  unsigned int i;
  if (ttisnil(key)) return 0;
  i = arrayindex(key, asize);
  if (i > 0) return i;
  {
    Node *n = luaH_mainposition(t, key);
    for (;;) {
      if (keyisempty(n))
        luaG_runerror(L, "invalid key to 'next'");
      if (luaV_rawequalobj(gkey(n), key))
        return cast_uint(n - t->node) + asize + 1;
      n = gnext(n);
      if (n == NULL) break;
    }
    luaG_runerror(L, "invalid key to 'next'");
    return 0;
  }
