/* object/number conversions */
#include "lobject.h"
#include "ldef.h"
#include "lstate.h"
#include "lstring.h"
#include "lmem.h"
#include "lvm.h"
#include "ltable.h"
#include "ldebug.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <ctype.h>
#include <stdarg.h>

#define LUAI_MAXNUMBER2STR 50

int luaO_hexavalue (int c) {
  if (c >= '0' && c <= '9') return c - '0';
  else if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  else if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  else return 0;
}

static int lis_space (int c) { return (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v'); }
static int lis_digit (int c) { return (c >= '0' && c <= '9'); }

/* convert a string to an integer; returns the number of bytes consumed (0 on failure) */
static size_t l_str2int (const char *s, size_t len, lua_Integer *result) {
  const char *e = s + len;
  const char *p = s;
  lua_Unsigned a = 0;
  int empty = 1;
  int neg = 0;
  const lua_Unsigned MAXA = (lua_Unsigned)(LUA_MAXINTEGER / 10);
  while (p < e && lis_space((unsigned char)*p)) p++;
  if (p < e && (*p == '-' || *p == '+')) { neg = (*p == '-'); p++; }
  if (p + 1 < e && p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
    p += 2;
    while (p < e && isxdigit((unsigned char)*p)) {
      a = a * 16 + luaO_hexavalue(*p);
      empty = 0;
      p++;
    }
  }
  else {
    for (; p < e && lis_digit((unsigned char)*p); p++) {
      int d = *p - '0';
      if (a >= MAXA && (a > MAXA || d > (LUA_MAXINTEGER % 10) + neg))
        return 0;  /* overflow */
      a = a * 10 + d;
      empty = 0;
    }
  }
  while (p < e && lis_space((unsigned char)*p)) p++;
  if (empty || p != e) return 0;
  *result = neg ? l_castU2S(0u - a) : l_castS2U(a);
  return (p - s);
}

static size_t l_str2d (const char *s, size_t len, lua_Number *result) {
  const char *endptr;
  const char *end = s + len;
  const char *p = s;
  while (p < end && lis_space((unsigned char)*p)) p++;
  if (p >= end) return 0;
  if (*p == '-' || *p == '+') {
    p++;
    if (p >= end || (!lis_digit((unsigned char)*p) && *p != '.')) return 0;
  }
  else if (!lis_digit((unsigned char)*p) && *p != '.') return 0;
  *result = (lua_Number)strtod(s, (char **)&endptr);
  if (endptr == s) return 0;
  while (endptr < end && lis_space((unsigned char)*endptr)) endptr++;
  if (endptr != end) return 0;
  return (endptr - s);
}

size_t luaO_str2num (const char *s, size_t len, TValue *o) {
  lua_Integer i;
  lua_Number d;
  size_t r;
  if ((r = l_str2int(s, len, &i)) != 0 && r == len) { setivalue(o, i); return 1; }
  if ((r = l_str2d(s, len, &d)) != 0 && r == len) { setfltvalue(o, d); return 1; }
  return 0;
}

/* convert a number to a string */
static int tostringbuff (lua_Number n, char *buff) {
  int len;
  int i;
  char tmp[LUAI_MAXNUMBER2STR];
  double back;
  for (i = 14; i <= 17; i++) {
    snprintf(tmp, sizeof(tmp), "%.*g", i, (double)n);
    back = strtod(tmp, NULL);
    if (back == (double)n || i == 17) break;
  }
  len = (int)strlen(tmp);
  memcpy(buff, tmp, len + 1);
  /* add ".0" if needed */
  if (strpbrk(buff, ".xXeEnN") == NULL) {
    buff[len++] = '.';
    buff[len++] = '0';
    buff[len] = '\0';
  }
  return len;
}

size_t luaO_tostringbuff (const TValue *o, char *buff) {
  if (ttisinteger(o))
    return snprintf(buff, LUAI_MAXNUMBER2STR, "%lld", (long long)ivalue(o));
  else if (ttisfloat(o))
    return tostringbuff(fltvalue(o), buff);
  buff[0] = '\0';
  return 0;
}

const char *luaO_typename (const TValue *o) {
  switch (o->tt) {
    case LUA_VNIL: return "nil";
    case LUA_VTRUE: case LUA_VFALSE: return "boolean";
    case LUA_VNUMINT: case LUA_VNUMFLT: return "number";
    case LUA_VSHRSTR: case LUA_VLNGSTR: return "string";
    case LUA_VTABLE: return "table";
    case LUA_VLCL: case LUA_VCCL: return "function";
    case LUA_VUSERDATA: return "userdata";
    case LUA_VTHREAD: return "thread";
    case LUA_TLIGHTUSERDATA: return "light userdata";
    default: return "unknown";
  }
}
C_EOF
echo ok"}

