static int tostringbuff (lua_Number n, char *buff) {
  int len;
  int i;
  char tmp[LUAI_MAXNUMBER2STR];
  double back;
  for (i = 14; i <= 17; i++) {
    snprintf(tmp, sizeof(tmp), "%.*g", i, (double)n);
    back = strtod(tmp, NULL);
    if (back == (double)n || i == 17) break;
  }
  len = (int)strlen(tmp);
  memcpy(buff, tmp, len + 1);
  /* add ".0" if needed */
  if (strpbrk(buff, ".xXeEnN") == NULL) {
    buff[len++] = '.';
    buff[len++] = '0';
    buff[len] = '\0';
  }
  return len;
