const char *luaO_typename (const TValue *o) {
  switch (o->tt) {
    case LUA_VNIL: return "nil";
    case LUA_VTRUE: case LUA_VFALSE: return "boolean";
    case LUA_VNUMINT: case LUA_VNUMFLT: return "number";
    case LUA_VSHRSTR: case LUA_VLNGSTR: return "string";
    case LUA_VTABLE: return "table";
    case LUA_VLCL: case LUA_VCCL: return "function";
    case LUA_VUSERDATA: return "userdata";
    case LUA_VTHREAD: return "thread";
    case LUA_TLIGHTUSERDATA: return "light userdata";
    default: return "unknown";
  }
}
