/* ------------------------------------------------------------ number conv */

int luaV_flttoint (lua_Number n, lua_Integer *p) {
  lua_Number f = floor(n);
  if (n != f) return 0;   /* not an integral value */
  if (f < (lua_Number)LUA_MININTEGER || f > (lua_Number)LUA_MAXINTEGER)
    return 0;
  *p = (lua_Integer)f;
  return 1;
}

lua_Integer luaV_tointwithf (lua_Integer i) {
  lua_Number d = (lua_Number)i;
  return (lua_Integer)d;
}

