** convert an object to an integer, without metamethods.
** mode: 0 = only integers (floats must have an exact integer value),
**       1 = floats are truncated (toward zero)?  (not used here)
*/
int luaV_tointegerns (const TValue *o, lua_Integer *i) {
  if (ttisinteger(o)) { *i = ivalue(o); return 1; }
  if (ttisfloat(o)) return luaV_flttoint(fltvalue(o), i);
  return 0;
}

int luaV_tointeger (const TValue *o, lua_Integer *i, int mode) {
  (void)mode;
  return luaV_tointegerns(o, i);
}

/* convert a value to a number (string conversions included) */
int luaV_tonumber_ (const TValue *o, TValue *n) {
  if (ttisnumber(o)) { setobj((TValue*)n, o); return 1; }
  if (ttisstring(o)) {
    char buf[64];
    size_t l = tsvalue(o)->length;
    if (l < sizeof(buf)) {
      memcpy(buf, tsvalue(o)->contents, l);
      buf[l] = '\0';
    }
    else return 0;
    if (luaO_str2num(buf, l, (TValue*)n) != 0) return 1;
  }
  return 0;
}

/* ------------------------------------------------------------ comparisons */

int luaV_rawequalobj (const TValue *t1, const TValue *t2) {
  if (t1->tt != t2->tt) {
    /* numbers of different subtypes may still be equal */
    if (ttisnumber(t1) && ttisnumber(t2)) {
      if (ttisinteger(t1)) {
        lua_Integer i1 = ivalue(t1);
        if (ttisfloat(t2)) {
          lua_Number f2 = fltvalue(t2);
          return ((lua_Number)i1 == f2);
        }
      }
      else {
        lua_Number f1 = fltvalue(t1);
        if (ttisinteger(t2)) {
          lua_Integer i2 = ivalue(t2);
          return (f1 == (lua_Number)i2);
        }
      }
    }
    return 0;
  }
  switch (t1->tt) {
    case LUA_VNIL: return 1;
    case LUA_VNUMINT: return (ivalue(t1) == ivalue(t2));
    case LUA_VNUMFLT: return (fltvalue(t1) == fltvalue(t2));
    case LUA_VTRUE: case LUA_VFALSE: return 1;
    case LUA_VSHRSTR: case LUA_VLNGSTR:
      if (tsvalue(t1)->length != tsvalue(t2)->length) return 0;
      return memcmp(tsvalue(t1)->contents, tsvalue(t2)->contents,
                    tsvalue(t1)->length) == 0;
    default:
      return gcvalue(t1) == gcvalue(t2);
  }
}

