static int lessequalothers (lua_State *L, const TValue *l, const TValue *r) {
  TValue rl, rr;
  if (tostringnum(l, &rl) && tostringnum(r, &rr))
    return luaV_lessequal(L, &rl, &rr);
  else if (luaV_callorderTM(L, l, r, "__le"))
    return 1;
  else if (luaV_callorderTM(L, l, r, "__lt"))  /* !(r < l) */
    return !(luaV_lessthan(L, r, l));
  luaG_ordererror(L, l, r);
  return 0;
}

int luaV_equalobj (lua_State *L, const TValue *t1, const TValue *t2) {
  if (luaV_rawequalobj(t1, t2)) return 1;
  if (ttistable(t1) && ttistable(t2))
    return luaV_callorderTM(L, t1, t2, "__eq");
  else if (ttisudata(t1) && ttisudata(t2))
    return luaV_callorderTM(L, t1, t2, "__eq");
  return 0;
}
