void luaT_callTMres (lua_State *L, const TValue *f, const TValue *p1,
                     const TValue *p2, TValue *res) {
  int oldtop = L->top;
  TValue *top;
  /* ensure stack space */
  luaD_checkstack(L, 5);
  top = L->stack + L->top;
  setobj2s(top, f);
