/* ------------------------------------------------------- metamethods ----- */

#define MAXLOOP 2000

static const char *tmnames[] = {
  "__index", "__newindex", "__gc", "__mode", "__len", "__eq",
  "__add", "__sub", "__mul", "__mod", "__pow", "__div", "__idiv",
  "__band", "__bor", "__bxor", "__shl", "__shr", "__unm", "__bnot",
  "__lt", "__le", "__concat", "__call", "__close", "__tostring", "__name",
  "__pairs", "__ipairs", "__metatable", NULL
};

enum {
  TM_INDEX = 0, TM_NEWINDEX, TM_GC, TM_MODE, TM_LEN, TM_EQ,
  TM_ADD, TM_SUB, TM_MUL, TM_MOD, TM_POW, TM_DIV, TM_IDIV,
  TM_BAND, TM_BOR, TM_BXOR, TM_SHL, TM_SHR, TM_UNM, TM_BNOT,
  TM_LT, TM_LE, TM_CONCAT, TM_CALL, TM_CLOSE, TM_TOSTRING, TM_NAME,
  TM_PAIRS, TM_IPAIRS, TM_METATABLE
};

const char *luaT_typemt (int tm) {
  return tmnames[tm];
}

/*
** Find a metamethod for object 'o' with name 'event'
*/
const TValue *luaT_gettmbyobj (lua_State *L, const TValue *o, int event) {
  Table *mt;
  if (ttistable(o)) mt = hvalue(o)->metatable;
  else if (ttisudata(o)) mt = uvalue(o)->metatable;
  else return &luaO_absentkey;
  if (mt == NULL) return &luaO_absentkey;
  return luaH_getshortstr(L, mt, tmnames[event]);
}

/*
** Call a metamethod with 2 args, return 1 result in 'res'
*/
void luaT_callTMres (lua_State *L, const TValue *f, const TValue *p1,
                     const TValue *p2, TValue *res) {
  int oldtop = L->top;
  TValue *top;
  /* ensure stack space */
  luaD_checkstack(L, 5);
  top = L->stack + L->top;
  setobj2s(top, f);
  setobj2s(top + 1, p1);
  setobj2s(top + 2, p2);
  L->top += 3;
  luaD_call(L, L->stack + L->top - 3, 1);
  /* result is at L->top - 1 */
  if (res != NULL)
    setobj2s(res, L->stack + L->top - 1);
  L->top = oldtop;
}

/*
** Call metamethod; return 1 if found and called (result on top of stack)
*/
static int callbinTM (lua_State *L, const TValue *p1, const TValue *p2,
                      TValue *res, int event) {
  const TValue *tm = luaT_gettmbyobj(L, p1, event);
  if (ttisnil(tm))
    tm = luaT_gettmbyobj(L, p2, event);
  if (ttisnil(tm)) return 0;
  luaT_callTMres(L, tm, p1, p2, res);
  return 1;
}

