/* ------------------------------------------------------------ objlen ----- */

void luaV_objlen (lua_State *L, TValue *ra, const TValue *rb) {
  const TValue *tm;
  switch (rb->tt) {
    case LUA_VTABLE: case LUA_VUSERDATA: {
      tm = luaT_gettmbyobj(L, rb, TM_LEN);
      if (!ttisnil(tm)) {
        luaT_callTMres(L, tm, rb, rb, ra);
        return;
      }
      if (ttistable(rb))
        setivalue(ra, luaH_getn(L, hvalue(rb)));
      else
        setivalue(ra, (lua_Integer)uvalue(rb)->len);
      return;
    }
    case LUA_VSHRSTR: case LUA_VLNGSTR:
      setivalue(ra, (lua_Integer)tsvalue(rb)->length);
      return;
    default:
      luaG_runerror(L, "attempt to get length of a %s value%s",
                    luaO_typename(rb), varinfo_(L, rb));
  }
}

/* --------------------------------------------------------- table access -- */

/*
** get a value from a table, honoring the __index metamethod
** 't' must be a table or userdata (or a value with __index)
*/
void luaV_gettable (lua_State *L, const TValue *t, TValue *key, TValue *val) {
  int loop;
  const TValue *slot;
  const TValue *tm = NULL;
  for (loop = 0; loop < MAXLOOP; loop++) {
    if (ttistable(t)) {
      slot = luaH_get(L, hvalue(t), key);
      if (!ttisnil(slot)) { setobj2s(val, slot); return; }
      tm = luaT_gettmbyobj(L, t, TM_INDEX);
      if (ttisnil(tm)) {
        setnilvalue(val);
        return;
      }
    }
    else if (ttisudata(t)) {
      tm = luaT_gettmbyobj(L, t, TM_INDEX);
      if (ttisnil(tm)) {
        /* userdata without __index: error */
        luaG_typeerror(L, t, "index");
        return;
      }
      slot = &luaO_absentkey;
    }
    else {
      tm = luaT_gettmbyobj(L, t, TM_INDEX);
      if (ttisnil(tm))
        luaG_typeerror(L, t, "index");
      slot = &luaO_absentkey;
    }
    if (ttisfunction(tm)) {
      luaT_callTMres(L, tm, t, key, val);
      return;
    }
    t = tm;   /* repeat with the metamethod */
  }
  luaG_runerror(L, "'__index' chain too long; maybe you are in a loop");
}

/*
** set a value in a table, honoring the __newindex metamethod
*/
void luaV_settable (lua_State *L, const TValue *t, TValue *key, TValue *val) {
  int loop;
  const TValue *tm = NULL;
  for (loop = 0; loop < MAXLOOP; loop++) {
    const TValue *slot;
    if (ttistable(t)) {
      slot = luaH_get(L, hvalue(t), key);
      if (!ttisnil(slot) ||
          (tm = luaT_gettmbyobj(L, t, TM_NEWINDEX), ttisnil(tm))) {
        TValue *p = luaH_set(L, hvalue(t), key);
        if (ttisnil(val)) setnilvalue(p);
        else setobj2t(p, val);
        return;
      }
    }
    else {
      tm = luaT_gettmbyobj(L, t, TM_NEWINDEX);
      if (ttisnil(tm))
        luaG_typeerror(L, t, "index");
    }
    if (ttisfunction(tm)) {
      /* call the metamethod: tm(t, key, val) */
      luaD_checkstack(L, 5);
      {
        int oldtop = L->top;
        TValue *top = L->stack + L->top;
        setobj2s(top, tm);
        setobj2s(top + 1, t);
        setobj2s(top + 2, key);
        setobj2s(top + 3, val);
        L->top += 4;
        luaD_call(L, L->stack + L->top - 4, 0);
        L->top = oldtop;
      }
      return;
    }
    t = tm;
  }
  luaG_runerror(L, "'__newindex' chain too long; maybe you are in a loop");
}
