          if (!ttisnil(slot)) { setobj2s(ra, slot); break; }
        }
        luaV_gettable(L, rb, k, ra);
        break;
      }
      case OP_GETTABLE: {
        TValue *rb = base + GET_B(i);
        TValue *rc = base + GET_C(i);
        if (ttistable(rb)) {
          const TValue *slot = luaH_get(L, hvalue(rb), rc);
          if (!ttisnil(slot)) { setobj2s(ra, slot); break; }
        }
