/* get the globals table */
Table *luaG_globals (lua_State *L) {
  Table *reg = hvalue(&G(L)->l_registry);
  TValue v;
  const TValue *p = luaH_getint(reg, LUA_RIDX_GLOBALS);
  if (ttistable(p)) return hvalue(p);
  /* create it */
  {
    Table *t = luaH_new(L);
    sethvalue(&v, t);
    luaC_fix(L, (GCObject *)t);
    setobj2t(luaH_setint(L, reg, LUA_RIDX_GLOBALS), &v);
    return t;
  }
}

