  global_State *g;
  lua_State *L;
  g = (global_State *)calloc(1, sizeof(global_State));
  if (g == NULL) return NULL;
  g->seed = (unsigned int)(size_t)g ^ (unsigned int)time(NULL);
  if (g->seed == 0) g->seed = 12345;
  g->gcstate = GCSpause;
  g->gcrunning = 1;
  g->gcsafe = 1;
  g->GCthreshold = 1000000;
  L = (lua_State *)calloc(1, sizeof(lua_State));
  if (L == NULL) { free(g); return NULL; }
