  g->mainthread = L;
  L->nextthread = NULL;
  L->tt = LUA_VTHREAD;
  L->marked = 1;
  L->status = LUA_OK;
  L->top = 0;
  L->stacksize = 0;
  L->errorJmp = NULL;
  L->openupval = NULL;
  L->hookmask = 0;
  L->hookcount = 0;
  L->nCcalls = 0;
  memset(&L->base_ci, 0, sizeof(CallInfo));
  L->base_ci.prev = NULL;
  L->base_ci.next = NULL;
  L->base_ci.func = 0;
  L->base_ci.top = 0;
  L->base_ci.callstatus = CIST_C;
  L->base_ci.nresults = 0;
  L->ci = &L->base_ci;
  {
    int sz = LUA_MINSTACK * 4;
    L->stack = (TValue *)calloc(1, sizeof(TValue) * sz);
    if (L->stack == NULL) { free(L); free(g); return NULL; }
    L->stacksize = sz;
