PYEOF
cat > lfunc.c <<'C_EOF'
/* functions, upvalues and finalizers */
#include "lfunc.h"
#include "lobject.h"
#include "ldef.h"
#include "lstate.h"
#include "lmem.h"
#include "lgc.h"
#include "ltable.h"
#include "lstring.h"
#include "lvm.h"
#include "ldebug.h"
#include "lapi.h"
#include <stdlib.h>

UpVal *luaF_findupval (lua_State *L, TValue *level) {
  UpVal **pp = &L->openupval;
  UpVal *p;
  while (*pp != NULL && (*pp)->v >= level) {
    if ((*pp)->v == level) return *pp;
    pp = &(*pp)->chain;
  }
  p = (UpVal *)luaM_new(L, UpVal);
  p->v = level;
  p->chain = *pp;
  *pp = p;
  setnilvalue(&p->value);
  luaC_link(L, (GCObject *)p, LUA_VUPVAL);
  return p;
}

void luaF_newupval (lua_State *L, int idx) {
  (void)L; (void)idx;
}

void luaF_close (lua_State *L, int level, int status, int yy) {
  (void)status; (void)yy;
  {
    TValue *levelptr = L->stack + level;
    UpVal *uv;
    while ((uv = L->openupval) != NULL && uv->v >= levelptr) {
      TValue *slot = uv->v;
      L->openupval = uv->chain;
      uv->chain = NULL;
      if (slot != &uv->value) {
        setobj(&uv->value, slot);
        uv->v = &uv->value;
      }
    }
  }
}

Closure *luaF_newLclosure (lua_State *L, int nelems) {
  Closure *c;
  size_t sz;
  if (nelems < 1) nelems = 1;
  sz = sizeof(Closure) + sizeof(UpVal *) * (size_t)(nelems - 1);
  c = (Closure *)luaM_alloc_(L, NULL, 0, sz);
  c->tt = LUA_VLCL;
  c->marked = 1;
  c->nupvalues = (unsigned char)nelems;
  c->isC = 0;
  c->f.p = NULL;
  luaC_link(L, (GCObject *)c, LUA_VLCL);
  return c;
}

Closure *luaF_newCclosure (lua_State *L, int nelems) {
  Closure *c;
  size_t sz;
  if (nelems < 1) nelems = 1;
  sz = sizeof(Closure) + sizeof(UpVal *) * (size_t)(nelems - 1);
  c = (Closure *)luaM_alloc_(L, NULL, 0, sz);
  c->tt = LUA_VCCL;
  c->marked = 1;
  c->nupvalues = (unsigned char)nelems;
  c->isC = 1;
  c->f.c = NULL;
  luaC_link(L, (GCObject *)c, LUA_VCCL);
  return c;
}

void luaF_callfinalizer (lua_State *L, GCObject *o) {
  TValue v;
  const TValue *tm;
  if (o->tt == LUA_VUSERDATA)
    setuvalue(&v, (Udata *)o);
  else if (o->tt == LUA_VTABLE)
    sethvalue(&v, (Table *)o);
  else return;
  tm = luaT_gettmbyobj(L, &v, TM_GC);
  if (ttisnil(tm)) return;
  {
    TValue *top = L->stack + L->top;
    luaD_checkstack(L, 2);
    top = L->stack + L->top;
    setobj2s(top, tm);
    setobj2s(top + 1, &v);
    L->top += 2;
    luaD_call(L, L->stack + L->top - 2, 0);
    L->top -= 2;
  }
}

void luaF_freeobj_ (lua_State *L, GCObject *o) {
  (void)L; (void)o;
}
C_EOF
echo ok

