/* stack-based API */
#include "lapi.h"
#include "lobject.h"
#include "ldef.h"
#include "lstate.h"
#include "lmem.h"
#include "lgc.h"
#include "lstring.h"
#include "ltable.h"
#include "lfunc.h"
#include "lvm.h"
#include "ldebug.h"
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdarg.h>

int apibase_ (lua_State *L) {
  return (L->ci == &L->base_ci) ? -1 : L->ci->func;
}

TValue *api_index_ (lua_State *L, int idx) {
  CallInfo *ci = L->ci;
  int base = apibase_(L);
  if (idx > 0) {
    TValue *o = L->stack + base + idx;
    if (o >= L->stack + L->top) return NULL;
    return o;
  }
  else if (idx > LUA_REGISTRYINDEX) {
    TValue *o = L->stack + L->top + idx;
    if (o < L->stack) return NULL;
    return o;
  }
  else if (idx == LUA_REGISTRYINDEX)
    return &G(L)->l_registry;
  else {
    /* upvalue of the current C function */
    Closure *cl;
    int n = LUA_REGISTRYINDEX - idx;
    if (L->ci == &L->base_ci) return NULL;
    if (!ttisclosure(s2v(L->stack + ci->func))) return NULL;
    cl = clvalue(s2v(L->stack + ci->func));
    if (n > cl->nupvalues) return NULL;
    return cl->upvals[n - 1]->v;
  }
}

static TValue *index2val (lua_State *L, int idx) {
  TValue *o = api_index_(L, idx);
  if (o == NULL) return NULL;
  return o;
}

/* -------------------------------------------------------------- stack --- */

int lua_gettop (lua_State *L) {
  return L->top - (apibase_(L) + 1);
}

void lua_settop (lua_State *L, int idx) {
  if (idx >= 0) {
    int n = idx;
    luaD_checkstack(L, n + 1);
    {
      int cur = L->top - (apibase_(L) + 1);
      int i;
      for (i = cur; i < n; i++)
        setnilvalue(L->stack + apibase_(L) + 1 + i);
      L->top = apibase_(L) + 1 + n;
    }
  }
  else {
    L->top = L->top + idx + 1;
    if (L->top < apibase_(L) + 1) L->top = apibase_(L) + 1;
  }
}

void lua_pop (lua_State *L, int n) {
  lua_settop(L, -n - 1);
}

void lua_pushvalue (lua_State *L, int idx) {
  TValue *o = api_index_(L, idx);
  TValue *top;
  if (o == NULL) { lua_pushnil(L); return; }
  luaD_checkstack(L, 1);
  top = L->stack + L->top;
  setobj2s(top, o);
  L->top++;
}

void lua_remove (lua_State *L, int idx) {
  TValue *o = api_index_(L, idx);
  TValue *p;
  if (o == NULL) return;
  for (p = o; p < L->stack + L->top - 1; p++)
    setobjs2s(p, p + 1);
  L->top--;
}

void lua_insert (lua_State *L, int idx) {
  TValue *o = api_index_(L, idx);
  TValue *p;
  if (o == NULL) return;
  luaD_checkstack(L, 1);
  for (p = L->stack + L->top; p > o; p--)
    setobjs2s(p, p - 1);
  L->top++;
}

void lua_replace (lua_State *L, int idx) {
  TValue *o = api_index_(L, idx);
  if (o == NULL) return;
  setobj2s(o, L->stack + L->top - 1);
}

void lua_copy (lua_State *L, int fromidx, int toidx) {
  TValue *f = api_index_(L, fromidx);
  TValue *t = api_index_(L, toidx);
  if (f == NULL || t == NULL) return;
  setobj2s(t, f);
}

int lua_type (lua_State *L, int idx) {
  TValue *o = api_index_(L, idx);
  if (o == NULL) return LUA_TNIL;
  return o->tt & 0x0f;
}

const char *lua_typename (lua_State *L, int tp) {
  (void)L;
  switch (tp) {
    case LUA_TNIL: return "nil";
    case LUA_TBOOLEAN: return "boolean";
    case LUA_TLIGHTUSERDATA: return "light userdata";
    case LUA_TNUMBER: return "number";
    case LUA_TSTRING: return "string";
    case LUA_TTABLE: return "table";
    case LUA_TFUNCTION: return "function";
    case LUA_TUSERDATA: return "userdata";
    case LUA_TTHREAD: return "thread";
    default: return "unknown";
  }
}

const char *lua_typenameT (int tp) { return lua_typename(NULL, tp); }

int lua_isnil (lua_State *L, int idx) { return lua_type(L, idx) == LUA_TNIL; }
int lua_isnone (lua_State *L, int idx) { return api_index_(L, idx) == NULL; }
int lua_isnoneornil (lua_State *L, int idx) {
  return api_index_(L, idx) == NULL || ttisnil(api_index_(L, idx));
}
int lua_isboolean (lua_State *L, int idx) { return lua_type(L, idx) == LUA_TBOOLEAN; }
int lua_isnumber (lua_State *L, int idx) {
  TValue *o = api_index_(L, idx);
  TValue n;
  if (o == NULL) return 0;
  if (ttisnumber(o)) return 1;
  if (ttisstring(o)) {
    char buf[64];
    size_t l = tsvalue(o)->length;
    if (l >= sizeof(buf)) return 0;
    memcpy(buf, tsvalue(o)->contents, l);
    buf[l] = '\0';
    return luaO_str2num(buf, l, &n) != 0;
  }
  return 0;
}
int lua_isstring (lua_State *L, int idx) {
  int t = lua_type(L, idx);
  return (t == LUA_TSTRING || t == LUA_TNUMBER);
}
int lua_istable (lua_State *L, int idx) { return lua_type(L, idx) == LUA_TTABLE; }
int lua_isfunction (lua_State *L, int idx) { return lua_type(L, idx) == LUA_TFUNCTION; }
int lua_iscfunction (lua_State *L, int idx) {
  TValue *o = api_index_(L, idx);
  return (o != NULL && ttisccl(o));
}
int lua_islightuserdata (lua_State *L, int idx) { return lua_type(L, idx) == LUA_TLIGHTUSERDATA; }
int lua_isuserdata (lua_State *L, int idx) {
  int t = lua_type(L, idx);
  return (t == LUA_TUSERDATA || t == LUA_TLIGHTUSERDATA);
}
int lua_isthread (lua_State *L, int idx) { return lua_type(L, idx) == LUA_TTHREAD; }
int lua_rawequal (lua_State *L, int idx1, int idx2) {
  TValue *o1 = api_index_(L, idx1);
  TValue *o2 = api_index_(L, idx2);
  if (o1 == NULL || o2 == NULL) return 0;
  return luaV_rawequalobj(o1, o2);
}
int lua_isequal (lua_State *L, int idx1, int idx2) {
  TValue *o1 = api_index_(L, idx1);
  TValue *o2 = api_index_(L, idx2);
  if (o1 == NULL || o2 == NULL) return 0;
  return luaV_equalobj(L, o1, o2);
}

/* ---------------------------------------------------------------- push -- */

void lua_pushnil (lua_State *L) {
  luaD_checkstack(L, 1);
  setnilvalue(L->stack + L->top);
  L->top++;
}

void lua_pushboolean (lua_State *L, int b) {
  luaD_checkstack(L, 1);
  if (b) setbtvalue(L->stack + L->top);
  else setbfvalue(L->stack + L->top);
  L->top++;
}

void lua_pushinteger (lua_State *L, lua_Integer n) {
  luaD_checkstack(L, 1);
  setivalue(L->stack + L->top, n);
  L->top++;
}

void lua_pushnumber (lua_State *L, lua_Number n) {
  luaD_checkstack(L, 1);
  setfltvalue(L->stack + L->top, n);
  L->top++;
}

const char *lua_pushlstring (lua_State *L, const char *s, size_t len) {
  TString *ts;
  luaD_checkstack(L, 1);
  ts = luaS_newlstr(L, s, len);
  setsvalue2s(L, L->stack + L->top, ts);
  L->top++;
  return ts->contents;
}

const char *lua_pushstring (lua_State *L, const char *s) {
  if (s == NULL) { lua_pushnil(L); return NULL; }
  return lua_pushlstring(L, s, strlen(s));
}

const char *lua_pushliteral (lua_State *L, const char *s) {
  return lua_pushlstring(L, s, strlen(s));
}

void lua_pushcclosure (lua_State *L, lua_CFunction fn, int n) {
  Closure *cl;
  int i;
  luaD_checkstack(L, 1);
  cl = luaF_newCclosure(L, n > 0 ? n : 1);
  cl->f.c = fn;
  for (i = 0; i < n; i++) {
    cl->upvals[i] = (UpVal *)luaM_new(L, UpVal);
    setobj(&cl->upvals[i]->value, L->stack + L->top - n + i);
    cl->upvals[i]->v = &cl->upvals[i]->value;
    cl->upvals[i]->chain = NULL;
    luaC_link(L, (GCObject *)cl->upvals[i], LUA_VUPVAL);
  }
  L->top -= n;
  setclvalue(L->stack + L->top, cl);
  L->top++;
}

void lua_pushcfunction (lua_State *L, lua_CFunction fn) {
  lua_pushcclosure(L, fn, 0);
}

void lua_pushlightuserdata (lua_State *L, void *p) {
  luaD_checkstack(L, 1);
  setpvalue(L->stack + L->top, p);
  L->top++;
}

void lua_createtable (lua_State *L, int narr, int nrec) {
  Table *t = luaH_new(L);
  TValue v;
  luaD_checkstack(L, 1);
  if (narr > 0) {
    unsigned int as = 1;
    while ((int)as < narr) as <<= 1;
    luaH_resizearray(L, t, as);
  }
  if (nrec > 0) {
    unsigned int hs = 1;
    while ((int)hs < nrec) hs <<= 1;
    luaH_resize(L, t, t->sizearray, hs);
  }
  sethvalue(&v, t);
  setobj2s(L->stack + L->top, &v);
  L->top++;
}

void *lua_newuserdata (lua_State *L, size_t size) {
  Udata *u;
  luaD_checkstack(L, 1);
  u = (Udata *)luaM_alloc_(L, NULL, 0, sizeof(Udata) + size);
  u->tt = LUA_VUSERDATA;
  u->marked = 1;
  u->len = size;
  u->metatable = NULL;
  u->env = NULL;
  if (size > 0) memset(u->contents, 0, size);
  luaC_link(L, (GCObject *)u, LUA_VUSERDATA);
  setuvalue(L->stack + L->top, u);
  L->top++;
  return u->contents;
}

lua_State *lua_newthread (lua_State *L) {
  lua_State *L1;
  global_State *g = G(L);
  luaD_checkstack(L, 1);
  L1 = (lua_State *)luaM_alloc_(L, NULL, 0, sizeof(lua_State));
  memset(L1, 0, sizeof(lua_State));
  L1->l_G = g;
  L1->nextthread = NULL;
  L1->tt = LUA_VTHREAD;
  L1->marked = 1;
  L1->status = LUA_OK;
  L1->stack = (TValue *)luaM_alloc_(L, NULL, 0, sizeof(TValue) * LUA_MINSTACK * 4);
