/* ------------------------------------------------------------ coroutine -- */

static void continuecoroutine_ (lua_State *L) {
  for (;;) {
    CallInfo *ci = L->ci;
    if (ci == &L->base_ci) return;
    if (isLua(ci)) {
      luaV_execute(L, NULL);
      continue;
    }
    else {
      /* C frame: run its continuation if it has one */
      if (ci->u.c.k != NULL) {
        int st = L->status;
        int nres;
        L->status = LUA_OK;
        ci->callstatus &= ~CIST_YIELDED;
        nres = (*(ci->u.c.k))(L, st, ci->u.c.ctx);
        L->nCcalls--;   /* the continuation ran as a C call */
        luaD_poscall(L, ci, nres);
        continue;
      }
      else {
        /* no continuation: abandon this frame */
        luaD_poscall(L, ci, 0);
        continue;
      }
    }
  }
}

struct ResumeData { int nargs; int retbase; };

static void do_resume_ (lua_State *L, int nargs, int retbase) {
  if (L->status == LUA_OK) {
    StkId func = L->stack + L->top - nargs - 1;
    luaD_call(L, func, LUA_MULTRET);
  }
  else {
    L->status = LUA_OK;
    continuecoroutine_(L);
  }
}

int lua_resume (lua_State *L, lua_State *from, int nargs) {
  int status;
  int retbase;
  int old_top;
  int old_ci_used = L->ci_used;
  int old_usedinblock = L->usedinblock;
  CallInfo *old_ci = L->ci;
  lua_longjmp lj;
  struct ResumeData rd;
  if (L->status == LUA_OK) {
    retbase = L->top - nargs - 1;
    old_top = retbase;
  }
  else {
    retbase = L->top - nargs;
    old_top = retbase;
  }
  rd.nargs = nargs;
  rd.retbase = retbase;
  lj.previous = L->errorJmp;
  lj.status = 0;
  L->errorJmp = &lj;
  if (setjmp(lj.b) == 0) {
    do_resume_(L, nargs, retbase);
    status = LUA_OK;
  }
  else
    status = lj.status;
  L->errorJmp = lj.previous;
  if (status != LUA_OK && status != LUA_YIELD) {
    TValue err;
    setobj(&err, L->stack + L->top - 1);
    L->ci = old_ci;
    L->ci_used = old_ci_used;
    L->usedinblock = old_usedinblock;
    L->top = retbase;
    setobj2s(L->stack + L->top, &err);
    L->top++;
    L->status = LUA_OK;
    luaF_close(L, retbase, status, 0);
    status = LUA_ERRRUN;
  }
  else if (status == LUA_YIELD) {
    /* move the yielded values to retbase */
    CallInfo *ci = L->ci;
    int n = L->top - (ci->func + 1);
    int i;
    if (n > 0) {
      TValue *src = L->stack + ci->func + 1;
      TValue *dst = L->stack + retbase;
      for (i = 0; i < n; i++)
        setobj2s(dst + i, src + i);
    }
    L->top = retbase + n;
    L->status = LUA_YIELD;
  }
  else {
    L->status = LUA_OK;
  }
  return status;
}

int lua_yieldk (lua_State *L, int nresults, lua_Integer ctx, lua_CFunctionK k) {
  CallInfo *ci = L->ci;
  if (L == G(L)->mainthread)
    luaG_runerror(L, "attempt to yield from outside a coroutine");
  if (ci == &L->base_ci)
    luaG_runerror(L, "attempt to yield from outside a coroutine");
  if (k == NULL && !isLua(ci))
    luaG_runerror(L, "attempt to yield across a C-call boundary");
  ci->u.c.k = k;
  ci->u.c.ctx = ctx;
  ci->callstatus |= CIST_YIELDED;
  L->status = LUA_YIELD;
  luaD_throw(L, LUA_YIELD);
  return 0;
}

int lua_yield (lua_State *L, int nresults) {
  return lua_yieldk(L, nresults, 0, yieldcont_);
}

static int yieldcont_ (lua_State *L, int status, lua_Integer ctx) {
  (void)status; (void)ctx;
  return lua_gettop(L);
}

int lua_isyieldable (lua_State *L) {
  return (L != G(L)->mainthread);
}

lua_State *lua_mainthread (lua_State *L) {
  return G(L)->mainthread;
}

void lua_xmove (lua_State *from, lua_State *to, int n) {
  int i;
  if (from == to) return;
  luaD_checkstack(to, n);
  for (i = 0; i < n; i++) {
    setobj2s(to->stack + to->top, from->stack + from->top - n + i);
    to->top++;
  }
  from->top -= n;
}

/* ----------------------------------------------------------------- misc -- */

int lua_errorlevel (lua_State *L, int level) {
  TValue *msg = L->stack + L->top - 1;
  if (ttisstring(msg)) {
    /* add position info */
    const char *where = luaG_where_(L, level);
    if (where != NULL && *where != '\0') {
      size_t l;
      const char *m = lua_tolstring(L, -1, &l);
      char *buff = (char *)luaM_alloc_(L, NULL, 0, strlen(where) + l + 2);
      size_t wl = strlen(where);
      memcpy(buff, where, wl);
      buff[wl] = ' ';
      memcpy(buff + wl + 1, m, l);
      buff[wl + 1 + l] = '\0';
      setsvalue2s(L, msg, luaS_newlstr(L, buff, wl + 1 + l));
      luaM_free(L, buff, wl + l + 2);
    }
  }
  return lua_error(L);
}

int lua_error (lua_State *L) {
  luaD_throw(L, LUA_ERRRUN);
  return 0;
}

int lua_gc (lua_State *L, int what, int data) {
  (void)data;
  switch (what) {
    case 0: return 0;   /* stop */
    case 1: return 0;   /* restart */
    case 2: return (int)(G(L)->totalbytes / 1024);   /* count */
    case 3: luaC_fullgc(L, 0); return 0;   /* collect */
    case 4: return 1;   /* count of steps? */
    default: return 0;
  }
}

size_t lua_gcbytes (lua_State *L) {
  return G(L)->totalbytes;
}

static void warnfdefault_ (void *ud, const char *msg, int tocont) {
  (void)ud;
  if (tocont)
    fprintf(stderr, "Lua warning: %s", msg);
  else
    fprintf(stderr, "\n");
}

void lua_setwarnf (lua_State *L, lua_WarnFunction f, void *ud) {
  G(L)->warnf = f;
  G(L)->warnud = ud;
}

void lua_warning (lua_State *L, const char *msg, int tocont) {
  (void)L;
  if (G(L)->warnf != NULL)
    (*G(L)->warnf)(G(L)->warnud, msg, tocont);
}
C_EOF
