static int findsetreg (Proto *p, int lastpc, int reg) {
  int pc;
  if (lastpc < 1) return -1;
  for (pc = lastpc - 1; pc >= 0; pc--) {
    Instruction i = p->code[pc];
    int op = GET_OP(i);
    int a = GET_A(i);
    int setit = 0;
    switch (op) {
      case OP_MOVE: case OP_LOADK: case OP_GETUPVAL: case OP_GETTABUP:
      case OP_GETFIELD: case OP_GETTABLE: case OP_SELF:
      case OP_ADD: case OP_SUB: case OP_MUL: case OP_MOD: case OP_POW:
      case OP_DIV: case OP_IDIV: case OP_BAND: case OP_BOR: case OP_BXOR:
      case OP_SHL: case OP_SHR: case OP_ADDK: case OP_SUBK: case OP_MULK:
      case OP_MODK: case OP_POWK: case OP_DIVK: case OP_IDIVK:
      case OP_BANDK: case OP_BORK: case OP_BXORK: case OP_SHLK: case OP_SHRK:
      case OP_UNM: case OP_BNOT: case OP_NOT: case OP_LEN: case OP_CONCAT:
      case OP_CLOSURE:
        setit = 1;
        break;
      case OP_LOADNIL:
        if (a <= reg && reg <= a + GET_B(i)) return -2;  /* ambiguous */
        break;
      default: break;
    }
    if (setit && a == reg)
      return pc;
  }
  return -1;
}

static const char *constname (Proto *p, int kidx) {
  if (kidx < 0 || kidx >= p->sizek) return NULL;
  if (ttisstring(&p->k[kidx])) return tsvalue(&p->k[kidx])->contents;
  if (ttisinteger(&p->k[kidx])) return "integer index";
  if (ttisfloat(&p->k[kidx])) {
    lua_Integer i;
    if (luaV_flttoint(fltvalue(&p->k[kidx]), &i)) return "integer index";
  }
  return NULL;
}

/*
** get a name for a register (register 'reg' in proto 'p' at pc 'lastpc')
*/
const char *getobjname_ (Proto *p, int lastpc, int reg, const char **name) {
  const char *n;
  int pc;
  Instruction i;
  int op;
  *name = NULL;
  n = luaF_getlocalname(p, lastpc, reg);
  if (n != NULL) {
    *name = n;
    return "local";
  }
  pc = findsetreg(p, lastpc, reg);
  if (pc < 0) return NULL;
  i = p->code[pc];
  op = GET_OP(i);
  switch (op) {
    case OP_MOVE: {
      int b = GET_B(i);
      if (b < GET_A(i))
        return getobjname_(p, pc, b, name);
      return NULL;
    }
    case OP_GETTABUP: {
      *name = constname(p, GET_C(i));
      return "global";
    }
    case OP_GETUPVAL: {
      Upvaldesc *uv = &p->upvalues[GET_B(i)];
      *name = uv->name ? uv->name->contents : NULL;
      return "upvalue";
    }
    case OP_GETFIELD: {
      *name = constname(p, GET_C(i));
      return "field";
    }
    case OP_GETTABLE: {
      /* the key is in a register: find its name */
      {
        const char *kn = NULL;
        const char *kkind = getobjname_(p, pc, GET_C(i), &kn);
        (void)kkind;
        *name = kn;
      }
      return "field";
    }
    case OP_SELF: {
      *name = constname(p, GET_C(i));
      return "method";
    }
    case OP_LOADK: {
      *name = constname(p, GET_Bx(i));
      return "constant";
    }
    default:
      return NULL;
  }
}

/* ------------------------------------------------------------ varinfo --- */

const char *varinfo_ (lua_State *L, const TValue *o) {
  static char buf[300];
  buf[0] = '\0';
  if (L == NULL) return buf;
  {
    CallInfo *ci = L->ci;
    if (isLua(ci)) {
      Proto *p = ci->u.l.p;
      int pc = ci->u.l.savedpc - 1;
      int base = ci->func + 1;
      const char *name = NULL;
      const char *kind = NULL;
      if (o >= L->stack && o < L->stack + L->stacksize) {
        int reg = (int)(o - (L->stack + base));
        if (reg >= 0 && reg < p->maxstacksize)
          kind = getobjname_(p, pc, reg, &name);
      }
      else if (p->k != NULL && o >= p->k && o < p->k + p->sizek) {
        kind = "constant";
        name = constname(p, (int)(o - p->k));
        if (name == NULL) {
          /* use the constant's string form */
          char tmp[LUAI_MAXNUMBER2STR];
          size_t l = luaO_tostringbuff(o, tmp);
          snprintf(buf, sizeof(buf), " (constant '%s')", tmp);
          return buf;
        }
      }
      if (kind != NULL && name != NULL)
        snprintf(buf, sizeof(buf), " (%s '%s')", kind, name);
    }
  }
  return buf;
}
C_EOF
