static const char *kindname (int kind) {
  switch (kind) {
    case 1: return "global";
    case 2: return "local";
    case 3: return "upvalue";
    case 4: return "field";
    case 5: return "method";
    default: return NULL;
  }
}

static const char *funcnamefromcall (lua_State *L, CallInfo *ci, const char **name) {
  CallInfo *prev = ci->prev;
  if (prev == NULL || prev == &L->base_ci) return NULL;
  if (isLua(prev)) {
    Proto *p = prev->u.l.p;
    int pc = prev->u.l.savedpc - 1;
    if (pc >= 0 && pc < p->sizecode && p->callsites != NULL) {
      CallSite *cs = &p->callsites[pc];
      if (cs->kind != 0 && cs->name != NULL) {
        *name = cs->name->contents;
        return kindname(cs->kind);
      }
    }
  }
  return NULL;
}

static const char *funcnamefromcode (lua_State *L, CallInfo *ci, const char **name) {
  Proto *p = ci->u.l.p;
  int pc = ci->u.l.savedpc - 1;
  if (pc < 0 || pc >= p->sizecode) return NULL;
  {
    Instruction i = p->code[pc];
    int op = GET_OP(i);
    switch (op) {
      case OP_TFORCALL:
        *name = "for iterator";
        return "for iterator";
      case OP_CALL: case OP_TAILCALL:
        return getobjname_(p, pc, GET_A(i), name);
      case OP_SELF:
        *name = constname(p, GET_C(i));
        return "metamethod";
      default:
        break;
    }
    /* metamethod-triggering instructions */
    switch (op) {
      case OP_GETTABUP: case OP_GETFIELD: case OP_GETTABLE:
      case OP_SETTABUP: case OP_SETFIELD: case OP_SETTABLE:
        *name = constname(p, GET_C(i));
        return "metamethod";
      default: break;
    }
  }
  return NULL;
}

const char *luaG_getfuncname (lua_State *L, CallInfo *ci, const char **name) {
  /* name for a C function frame */
  return funcnamefromcall(L, ci, name);
}
