      l = bufflen - prefix - 10;
      memcpy(buff, "[string \"", 9);
      memcpy(buff + 9, src->contents, l);
      memcpy(buff + 9 + l, "\"]", 2);
      buff[9 + l + 2] = '\0';
      /* append "..." if truncated */
      if (len > l) {
