/* ---------------------------------------------------------- traceback --- */

void luaL_traceback (lua_State *L, lua_State *L1, const char *msg, int level) {
  luaL_Buffer b;
  CallInfo *ci;
  int i;
  luaL_buffinit(L1, &b);
  if (msg != NULL)
    luaL_addstring(&b, msg);
  luaL_addstring(&b, "\nstack traceback:");
  /* walk the CallInfo chain, starting 'level' frames above the current one */
  ci = L1->ci;
  for (i = 0; i < level && ci != NULL && ci != &L1->base_ci; i++)
    ci = ci->prev;
  for (; ci != NULL && ci != &L1->base_ci; ci = ci->prev) {
    char line[64];
    const char *name = NULL;
    const char *kind = NULL;
    char srcbuf[130];
    int what = 0;
    luaL_addchar(&b, '\n');
    luaL_addchar(&b, '\t');
    if (isLua(ci)) {
      Proto *p = ci->u.l.p;
      int curline = luaG_currentline(L1, ci);
      chunkid_(srcbuf, sizeof(srcbuf), p->source);
      luaL_addstring(&b, srcbuf);
      if (curline >= 0) {
        snprintf(line, sizeof(line), ":%d:", curline);
        luaL_addstring(&b, line);
      }
      if (p->linedefined == 0 && p->lastlinedefined == 0) {
        name = "main chunk";
        what = 1;
      }
      else {
        kind = funcnamefromcall(L1, ci, &name);
        if (kind == NULL)
          kind = funcnamefromcode(L1, ci, &name);
      }
    }
    else {
      /* C function */
      kind = funcnamefromcall(L1, ci, &name);
      if (kind == NULL)
        name = NULL;
      luaL_addstring(&b, "[C]");
    }
    if (!what) {
      if (kind != NULL && name != NULL) {
        char tmp[260];
        snprintf(tmp, sizeof(tmp), "%s '%s'", kind, name);
        luaL_addstring(&b, tmp);
      }
      else
        luaL_addstring(&b, "?");
    }
    else {
      luaL_addstring(&b, name);
    }
    luaL_addstring(&b, " in ");
    {
      char tmp[300];
      if (kind != NULL && name != NULL)
        snprintf(tmp, sizeof(tmp), "%s '%s'", kind, name);
      else if (what)
        snprintf(tmp, sizeof(tmp), "%s", name);
      else
        snprintf(tmp, sizeof(tmp), "?");
      luaL_addstring(&b, tmp);
    }
  }
  luaL_addstring(&b, "\n");
  {
    size_t l;
    char *s = luaL_buffresult_(&b, &l);
    luaD_checkstack(L1, 1);
    setsvalue2s(L1, L1->stack + L1->top, luaS_newlstr(L1, s, l));
    L1->top++;
  }
}

/* -------------------------------------------------------------- hooks --- */

void luaG_hookevent (lua_State *L, int event, CallInfo *ci) {
  lua_Debug ar;
  if (L->hook == NULL) return;
  memset(&ar, 0, sizeof(ar));
  ar.L1 = L;
  ar.event = event;
  ar.i_ci = 0;
  (*L->hook)(L, &ar);
}

static void hookcheck_ (lua_State *L, CallInfo *ci) {
  if (L->hookmask & LUA_MASKCOUNT) {
    L->hookcount--;
    if (L->hookcount <= 0) {
      L->hookcount = L->hookL;
      if (L->hook != NULL)
        luaG_hookevent(L, LUA_HOOKCOUNT, ci);
    }
  }
  if (L->hookmask & LUA_MASKLINE && isLua(ci)) {
    Proto *p = ci->u.l.p;
    int pc = ci->u.l.savedpc - 1;
    if (pc >= 0 && pc < p->sizecode) {
      static int lastline = -1;
      int line = p->lineinfo ? p->lineinfo[pc] : -1;
      if (line != lastline) {
        lastline = line;
        if (L->hook != NULL)
          luaG_hookevent(L, LUA_HOOKLINE, ci);
      }
    }
  }
}
