const char *luaO_pushvfstring (lua_State *L, const char *fmt, va_list args) {
  char buff[1024];
  size_t blen = 0;
  const char *f = fmt;
  char tmp[MAXFORMAT];
  while (*f != '\0') {
    if (*f != '%') {
      if (blen + 1 < sizeof(buff)) buff[blen++] = *f;
      f++;
      continue;
    }
    f++;
    {
      int width = 0, prec = -1;
      char spec[32];
      int slen = 0;
      /* parse flags, width, precision */
      while (*f == '-' || *f == '+' || *f == ' ' || *f == '#' || *f == '0') {
        if (slen < 30) spec[slen++] = *f;
        f++;
      }
      while (*f >= '0' && *f <= '9') {
        if (slen < 30) spec[slen++] = *f;
        f++;
      }
      if (*f == '.') {
        if (slen < 30) spec[slen++] = *f;
        f++;
        while (*f >= '0' && *f <= '9') {
          if (slen < 30) spec[slen++] = *f;
          f++;
        }
      }
      spec[slen] = '\0';
      switch (*f) {
        case 's': {
          const char *s = va_arg(args, const char *);
          if (s == NULL) s = "(null)";
          blen += (size_t)snprintf(buff + blen, sizeof(buff) - blen, "%s%s", spec, s);
          break;
        }
        case 'd': {
          int d = va_arg(args, int);
          blen += (size_t)snprintf(buff + blen, sizeof(buff) - blen, "%s%d", spec, d);
          break;
        }
        case 'I': {
          lua_Integer d = va_arg(args, lua_Integer);
          blen += (size_t)snprintf(buff + blen, sizeof(buff) - blen, "%s%lld", spec, (long long)d);
          break;
        }
        case 'c': {
          int c = va_arg(args, int);
          if (blen + 1 < sizeof(buff)) buff[blen++] = (char)c;
          break;
        }
        case 'f': case 'F': case 'e': case 'E': case 'g': case 'G': {
          double d = va_arg(args, double);
          blen += (size_t)snprintf(buff + blen, sizeof(buff) - blen, "%s%c", spec, *f);
          break;
        }
        case 'p': {
          void *p = va_arg(args, void *);
          blen += (size_t)snprintf(buff + blen, sizeof(buff) - blen, "%p", p);
          break;
        }
        case '%': {
          if (blen + 1 < sizeof(buff)) buff[blen++] = '%';
          break;
        }
        default: {
          if (blen + 2 < sizeof(buff)) { buff[blen++] = '%'; buff[blen++] = *f; }
          break;
        }
      }
      if (*f != '\0') f++;
    }
    (void)tmp;
  }
  buff[blen] = '\0';
  luaD_checkstack(L, 1);
  setsvalue2s(L, L->stack + L->top, luaS_newlstr(L, buff, blen));
  L->top++;
  return buff;
}

const char *luaO_pushfstring (lua_State *L, const char *fmt, ...) {
  va_list args;
  const char *s;
  va_start(args, fmt);
  s = luaO_pushvfstring(L, fmt, args);
  va_end(args);
  return s;
}

/*
** format a chunk name: '"..."', '="..."', or '[string "..."]'
*/
void chunkid_ (char *buff, size_t bufflen, TString *src) {
  size_t len;
  if (src == NULL) {
    buff[0] = '?';
    buff[1] = '\0';
    return;
  }
  len = src->length;
  if (*src->contents == '=') {
    /* remove the '=' and copy the rest */
    len--;
    if (len >= bufflen) len = bufflen - 1;
    memcpy(buff, src->contents + 1, len);
    buff[len] = '\0';
  }
  else if (*src->contents == '@') {
    len--;
    if (len >= bufflen) { len = bufflen - 5; memcpy(buff, "...", 3); }
    else memcpy(buff, src->contents + 1, len);
    buff[len] = '\0';
  }
  else {  /* string chunk */
    size_t l = len;
    int prefix = 4;   /* "[string " */
    if (l > bufflen - prefix - 10) {
      l = bufflen - prefix - 10;
      memcpy(buff, "[string \"", 9);
      memcpy(buff + 9, src->contents, l);
      memcpy(buff + 9 + l, "\"]", 2);
      buff[9 + l + 2] = '\0';
      /* append "..." if truncated */
      if (len > l) {
        memcpy(buff + 9 + l - 3, "...", 3);
      }
      return;
    }
    memcpy(buff, "[string \"", 9);
    memcpy(buff + 9, src->contents, l);
    buff[9 + l] = '"';
    buff[9 + l + 1] = ']';
    buff[9 + l + 2] = '\0';
  }
}
