  "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
  "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return", "then",
  "true", "until", "while", "::", "...", "==", "~=", "<=", ">=", "//", "<<", ">>"
};

static const int tokcodes[] = {
  TK_AND, TK_BREAK, TK_DO, TK_ELSE, TK_ELSEIF, TK_END, TK_FALSE, TK_FOR,
  TK_FUNCTION, TK_GOTO, TK_IF, TK_IN, TK_LOCAL, TK_NIL, TK_NOT, TK_OR,
  TK_REPEAT, TK_RETURN, TK_THEN, TK_TRUE, TK_UNTIL, TK_WHILE, TK_DBCOLON,
  TK_ELLIPSIS, TK_EQ, TK_NE, TK_LE, TK_GE, TK_IDIV, TK_SHL, TK_SHR
};

#define NUMRESERVED ((int)(sizeof(tokcodes)/sizeof(tokcodes[0])))

static int isreserved (const char *name) {
  int i;
  for (i = 0; i < NUMRESERVED; i++)
    if (strcmp(name, luaX_tokens[i]) == 0) return tokcodes[i];
  return 0;
}

static void savechar (LexState *ls, int c) {
  Mbuffer *b = &ls->buff;
  if (b->n + 1 >= b->buffsize) {
    size_t newsize = b->buffsize * 2;
    char *nb;
    if (newsize < 32) newsize = 32;
    nb = (char *)luaM_alloc_(ls->L, b->buffer, b->buffsize, newsize);
    b->buffer = nb;
    b->buffsize = newsize;
  }
  b->buffer[b->n++] = (char)c;
}

static TString *buff2str (LexState *ls) {
  Mbuffer *b = &ls->buff;
  TString *ts = luaS_newlstr(ls->L, b->buffer, b->n);
  b->n = 0;
  return ts;
}

static int nextc (LexState *ls) {
  if (ls->pos < ls->zlen)
    ls->current = (unsigned char)ls->z[ls->pos++];
  else
    ls->current = -1;
  return ls->current;
}

void luaX_setinput (lua_State *L, LexState *ls, TString *src, const char *z, size_t len) {
  ls->L = L;
  ls->source = src;
  ls->z = z;
  ls->zlen = len;
  ls->pos = 0;
  ls->linenumber = 1;
  ls->lastline = 1;
  ls->current = 0;
  ls->buff.buffer = NULL;
  ls->buff.buffsize = 0;
  ls->buff.n = 0;
  ls->tstring = NULL;
  ls->ttoken = 0;
  ls->lookahead = -1;
  ls->fs = NULL;
