    lua_State *L = ls->L;
    luaD_checkstack(L, 1);
    setsvalue2s(L, L->stack + L->top, luaS_new(L, msg));
    L->top++;
    setsvalue2s(L, L->stack + L->top, ls->source);
    L->top++;
    setivalue(L->stack + L->top, ls->linenumber);
    L->top++;
  }
  luaD_throw(ls->L, LUA_ERRSYNTAX);
}

