    if (ls->current == '.') {
      dot = 1;
      savechar(ls, nextc(ls));
      while (lis_xdigit(ls->current)) savechar(ls, nextc(ls));
    }
    if (ls->current == 'p' || ls->current == 'P') {
      savechar(ls, nextc(ls));
      if (ls->current == '+' || ls->current == '-')
        savechar(ls, nextc(ls));
      while (lis_digit(ls->current)) savechar(ls, nextc(ls));
    }
  }
  else {
    while (lis_digit(ls->current)) savechar(ls, nextc(ls));
    if (ls->current == '.' && !dot) {
      dot = 1;
      savechar(ls, nextc(ls));
      while (lis_digit(ls->current)) savechar(ls, nextc(ls));
    }
    if (ls->current == 'e' || ls->current == 'E') {
      exp = 1;
      savechar(ls, nextc(ls));
      if (ls->current == '+' || ls->current == '-')
        savechar(ls, nextc(ls));
      while (lis_digit(ls->current)) savechar(ls, nextc(ls));
    }
  }
