    nextc(ls);
    if (ls->current == '\n') nextc(ls);
    ls->linenumber++;
  }
  else if (ls->current == '\n') {
    nextc(ls);
    ls->linenumber++;
  }
  else nextc(ls);
}

static int check_long_string (LexState *ls) {
  /* after '[' check for '=' or '[' */
  if (ls->current == '[') {
    nextc(ls);
    return 2;   /* level 0 */
  }
  else if (ls->current == '=') {
    int level = 1;
    while (ls->current == '=') { nextc(ls); level++; }
    if (ls->current == '[') { nextc(ls); return level; }
    return -1;
  }
  return 0;
}

static void read_long_string (LexState *ls, SemInfo *seminfo, int level) {
  int firstline = ls->linenumber;
  nextc(ls);   /* skip the second '[' */
  if (ls->current == '\r') { nextc(ls); if (ls->current == '\n') nextc(ls); ls->linenumber++; }
  else if (ls->current == '\n') { nextc(ls); ls->linenumber++; }
  for (;;) {
    switch (ls->current) {
      case -1: lexerror_(ls, "unfinished long string", -1); return;
      case ']': {
        nextc(ls);
        if (ls->current == ']') {
          nextc(ls);
          return;
        }
        savechar(ls, ']');
        break;
      }
      case '\r': {
        nextc(ls);
        if (ls->current == '\n') { savechar(ls, '\n'); nextc(ls); }
        else savechar(ls, '\r');
        ls->linenumber++;
        break;
      }
      case '\n': savechar(ls, '\n'); nextc(ls); ls->linenumber++; break;
      case '=': {
        int lvl = check_long_string(ls);
        if (lvl == level) { nextc(ls); return; }
        else if (lvl > 0) { int i; for (i = 0; i < lvl + 1; i++) savechar(ls, '='); savechar(ls, '['); }
        else savechar(ls, '=');
        break;
      }
      case '[': {
        nextc(ls);
        savechar(ls, '[');
        break;
      }
      default: savechar(ls, ls->current); nextc(ls); break;
    }
  }
}

int luaX_next (LexState *ls) {
