      }
      case '=': {
        nextc(ls);
        if (ls->current == '=') { nextc(ls); t = TK_EQ; }
        else t = '=';
        ls->ttoken = t;
        ls->tstring = NULL;
        return t;
      }
      case '<': {
        nextc(ls);
        if (ls->current == '=') { nextc(ls); t = TK_LE; }
        else if (ls->current == '<') { nextc(ls); t = TK_SHL; }
        else t = '<';
        ls->ttoken = t;
        ls->tstring = NULL;
        return t;
      }
      case '>': {
        nextc(ls);
        if (ls->current == '=') { nextc(ls); t = TK_GE; }
        else if (ls->current == '>') { nextc(ls); t = TK_SHR; }
        else t = '>';
        ls->ttoken = t;
        ls->tstring = NULL;
        return t;
      }
      case '/': {
        nextc(ls);
        if (ls->current == '/') { nextc(ls); t = TK_IDIV; }
        else t = '/';
        ls->ttoken = t;
        ls->tstring = NULL;
