            ls->ttoken = TK_NAME;
            ls->tstring = ts;
            return TK_NAME;
          }
        }
        else {
          ls->ttoken = c;
          ls->tstring = NULL;
          nextc(ls);
          return c;
        }
      }
    }
  }
}
