static int gethexa (int c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

static void readhexaesc (LexState *ls, int *r) {
  int c1 = gethexa(ls->current);
  int c2;
  if (c1 < 0) lexerror_(ls, "hexadecimal digit expected", -1);
  nextc(ls);
  c2 = gethexa(ls->current);
  if (c2 < 0) lexerror_(ls, "hexadecimal digit expected", -1);
  nextc(ls);
  *r = (c1 << 4) + c2;
}

static void readutf8esc (LexState *ls) {
  int i;
