  nextc(ls);   /* skip '{' */
  if (ls->current == '}') lexerror_(ls, "UTF-8 value missing", -1);
  do {
    int c = gethexa(ls->current);
    if (c < 0) lexerror_(ls, "hexadecimal digit expected", -1);
    r = (r << 4) | (unsigned int)c;
    if (r > 0x7FFFFFFF) lexerror_(ls, "UTF-8 value too large", -1);
    nextc(ls);
