  else if (r < 0x200000) {
    savechar(ls, 0xF0 | (int)(r >> 18));
    savechar(ls, 0x80 | (int)((r >> 12) & 0x3F));
    savechar(ls, 0x80 | (int)((r >> 6) & 0x3F));
    savechar(ls, 0x80 | (int)(r & 0x3F));
