/* ---------------------------------------------------------- expressions -- */

static void init_exp (expdesc *e, ExpKind k, int info) {
  e->k = k;
  e->t = NOJUMP;
  e->f = NOJUMP;
  e->info = info;
  e->reg = NOREG;
  e->idx = NOREG;
  e->nres = 0;
}

/* free the registers used by an expression */
static void freeexp (FuncState *fs, expdesc *e) {
  switch (e->k) {
    case VNONRELOC: case VLOCAL: case VCALL: case VVARARG: case VINDEXED: {
      if (e->reg >= fs->nactvar)
        fs->freereg = e->reg;
      break;
    }
    default: break;
  }
}

/* put the expression's value into a register */
static void discharge2reg (FuncState *fs, expdesc *e, int reg) {
  switch (e->k) {
    case VVOID: case VNIL:
      codeABC(fs, OP_LOADNIL, reg, 0, 0);
      break;
    case VTRUE:
      codeABC(fs, OP_LOADBOOL, reg, 1, 0);
      break;
    case VFALSE:
      codeABC(fs, OP_LOADBOOL, reg, 0, 0);
      break;
    case VK:
      codeABx(fs, OP_LOADK, reg, e->info);
      break;
    case VLOCAL:
      if (reg != e->reg)
        codeABC(fs, OP_MOVE, reg, e->reg, 0);
      break;
    case VUPVAL:
      codeABC(fs, OP_GETUPVAL, reg, e->info, 0);
      break;
    case VINDEXED: {
      int tb = e->reg;
      if (e->idx >= 0)
        codeABC(fs, OP_GETTABLE, reg, tb, e->idx);
      else
        codeABx(fs, OP_GETFIELD, reg, tb, -1 - e->idx);
      break;
    }
    case VVARARG:
      codeABx(fs, OP_VARARG, reg, 2);
      break;
    case VCALL: {
      /* the call results are already in e->reg */
      if (reg != e->reg)
        codeABC(fs, OP_MOVE, reg, e->reg, 0);
      break;
    }
    case VNONRELOC:
      if (reg != e->reg)
        codeABC(fs, OP_MOVE, reg, e->reg, 0);
      break;
  }
  e->k = VNONRELOC;
  e->reg = reg;
  e->t = NOJUMP;
  e->f = NOJUMP;
