/* parser and code generator */
#include "lparser.h"
#include "lobject.h"
#include "ldef.h"
#include "lstate.h"
#include "llex.h"
#include "lstring.h"
#include "lmem.h"
#include "ltable.h"
#include "lvm.h"
#include "lfunc.h"
#include "ldebug.h"
#include "lapi.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>

#define NOJUMP    (-1)
#define NOREG     (-1)
#define LFIELDS    50

typedef struct BlockCnt {
  struct BlockCnt *previous;
  int firstlabel;
  int firstgoto;
  int nactvar;
  int upval;
  int insideloop;
} BlockCnt;

typedef struct Labeldesc {
  TString *name;
  int pc;
  int line;
  int resolved;
} Labeldesc;

typedef struct FuncState {
  Proto *f;
  struct FuncState *prev;
  LexState *ls;
  BlockCnt *bl;
  int nk;
  int nactvar;
  int freereg;
  int pc;
  int jpc;
  int needclose;
  Labeldesc *labels;
  int nlabels, labsize;
  Labeldesc *gotos;
  int ngotos, gotsize;
} FuncState;

typedef enum {
  VVOID, VNIL, VTRUE, VFALSE, VK, VLOCAL, VUPVAL, VINDEXED,
  VUPVALINDEXED, VVARARG, VCALL, VNONRELOC
} ExpKind;

typedef struct expdesc {
  ExpKind k;
  int t;        /* patch list for 'go if true' */
  int f;        /* patch list for 'go if false' */
  int info;     /* VK: constant index; VUPVAL: upvalue index; VCALL: call pc */
  int reg;      /* register holding the value (VINDEXED: table register) */
  int idx;      /* VINDEXED: key register (>=0) or -1-constidx */
  int nres;     /* VCALL/VVARARG: number of results */
  int isupval;  /* VINDEXED: 1 if the table is an upvalue */
} expdesc;

/* ----------------------------------------------------------- codegen ---- */

static void checkstack (FuncState *fs, int n) {
  if (fs->freereg + n > MAXSTACK)
    luaX_syntaxerror(fs->ls, "function or expression needs too many registers");
  if (fs->f->maxstacksize < fs->freereg + n)
    fs->f->maxstacksize = fs->freereg + n;
}

static void reserve (FuncState *fs, int n) {
  checkstack(fs, n);
  fs->freereg += n;
}

static void code (FuncState *fs, Instruction i, int line) {
  Proto *f = fs->f;
  lua_State *L = fs->ls->L;
  if (fs->pc >= f->sizecode) {
    int oldsize = f->sizecode;
    int newsize = oldsize * 2;
    Instruction *nc;
    int *nl;
    CallSite *ncs;
    if (newsize < 8) newsize = 8;
    nc = (Instruction *)luaM_alloc_(L, f->code, sizeof(Instruction)*oldsize,
                                    sizeof(Instruction)*newsize);
    f->code = nc;
    nl = (int *)luaM_alloc_(L, f->lineinfo, sizeof(int)*oldsize, sizeof(int)*newsize);
    f->lineinfo = nl;
    ncs = (CallSite *)luaM_alloc_(L, f->callsites, sizeof(CallSite)*oldsize,
                                  sizeof(CallSite)*newsize);
    f->callsites = ncs;
    f->sizecode = newsize;
  }
  f->code[fs->pc] = i;
  f->lineinfo[fs->pc] = line;
  f->callsites[fs->pc].name = NULL;
  f->callsites[fs->pc].kind = 0;
  fs->pc++;
}

static int codeABC (FuncState *fs, int op, int a, int b, int c) {
  code(fs, MAKE_OP(op, a, b, c), fs->ls->lastline);
  return fs->pc - 1;
}

static int codeABx (FuncState *fs, int op, int a, int bx) {
  code(fs, MAKE_OP(op, a, (bx) & 0xff, ((unsigned)(bx) >> 8) & 0xff), fs->ls->lastline);
  return fs->pc - 1;
}

static int codeAsBx (FuncState *fs, int op, int a, int sbx) {
  return codeABx(fs, op, a, sbx + 0x8000);
}

static int codeAB (FuncState *fs, int op, int a, int b) {
  return codeABC(fs, op, a, b, 0);
}

/* ------------------------------------------------------------- jumps ---- */

static int getjump (FuncState *fs, int pc) {
  Instruction i = fs->f->code[pc];
  int offset = GET_sBx(i);
  if (offset == NOJUMP) return NOJUMP;
  return pc + 1 + offset;
}

static void fixjump (FuncState *fs, int pc, int dest) {
  Instruction i = fs->f->code[pc];
  int offset = dest - (pc + 1);
  if (offset < -0x8000 || offset > 0x7fff)
    luaX_syntaxerror(fs->ls, "control structure too long");
  fs->f->code[pc] = MAKE_JUMP(GET_OP(i), GET_A(i), offset);
}

static void concat (FuncState *fs, int *l1, int l2) {
  if (l2 == NOJUMP) return;
  if (*l1 == NOJUMP) { *l1 = l2; return; }
  else {
    int list = *l1;
    int next;
    while ((next = getjump(fs, list)) != NOJUMP) list = next;
    fixjump(fs, list, l2);
  }
}

static void patchlistaux (FuncState *fs, int list, int target, int reg, int dtarget) {
  while (list != NOJUMP) {
    int next = getjump(fs, list);
    if (reg != NOREG)
      fixjump(fs, list, dtarget);
    else
      fixjump(fs, list, target);
    list = next;
  }
}

static int getfinaltarget (FuncState *fs, int pc) {
  int dest = getjump(fs, pc);
  if (dest != NOJUMP && GET_sBx(fs->f->code[dest]) == NOJUMP)
    return getfinaltarget(fs, dest);
  else return pc;
}

static void patchlist (FuncState *fs, int list, int target) {
  if (list == NOJUMP) return;
  getfinaltarget(fs, list);
  patchlistaux(fs, list, target, NOREG, target);
}

static void patchtohere (FuncState *fs, int list) {
  if (list == NOJUMP) return;
  patchlist(fs, list, fs->pc);
}

static int newjump (FuncState *fs) {
  int pc = codeAsBx(fs, OP_JMP, 0, 0);
  fs->f->code[pc] = MAKE_JUMP(OP_JMP, 0, NOJUMP);
  return pc;
}

/* ----------------------------------------------------------- constants -- */

static int addk (FuncState *fs, TValue *v) {
  Proto *f = fs->f;
  int i;
  for (i = 0; i < fs->nk; i++) {
    if (luaV_rawequalobj(&f->k[i], v))
      return i;
  }
  if (fs->nk >= f->sizek) {
    int oldsize = f->sizek;
    int newsize = oldsize * 2;
    TValue *nk;
    if (newsize < 8) newsize = 8;
    nk = (TValue *)luaM_alloc_(fs->ls->L, f->k, sizeof(TValue)*oldsize,
                               sizeof(TValue)*newsize);
    f->k = nk;
    f->sizek = newsize;
  }
  setobj2t(&f->k[fs->nk], v);
  fs->nk++;
  return fs->nk - 1;
}

static int stringK (FuncState *fs, TString *ts) {
  TValue v;
  setsvalue(&v, ts);
  return addk(fs, &v);
}

static int intK (FuncState *fs, lua_Integer i) {
  TValue v;
  setivalue(&v, i);
  return addk(fs, &v);
}

static int fltK (FuncState *fs, lua_Number r) {
  TValue v;
  setfltvalue(&v, r);
  return addk(fs, &v);
}

/* -------------------------------------------------------------- locals -- */

static int newlocalvar (LexState *ls, TString *name) {
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  if (f->sizelocvars <= fs->nactvar) {
    int oldsize = f->sizelocvars;
    int newsize = (oldsize < 4) ? 4 : oldsize * 2;
    LocVar *nl;
    nl = (LocVar *)luaM_alloc_(ls->L, f->locvars, sizeof(LocVar)*oldsize,
                               sizeof(LocVar)*newsize);
    f->locvars = nl;
    f->sizelocvars = newsize;
  }
  f->locvars[fs->nactvar].varname = name;
  f->locvars[fs->nactvar].startpc = fs->pc;
  f->locvars[fs->nactvar].endpc = 0;
  fs->nactvar++;
  return fs->nactvar - 1;
}

static void removevars (FuncState *fs, int tolevel) {
  while (fs->nactvar > tolevel) {
    fs->nactvar--;
    fs->f->locvars[fs->nactvar].endpc = fs->pc;
  }
  if (fs->freereg > tolevel)
    fs->freereg = tolevel;
}

/* ------------------------------------------------------------ upvalues -- */

static int searchupvalue (FuncState *fs, TString *name) {
  int i;
  for (i = 0; i < fs->f->sizeupvalues; i++)
    if (fs->f->upvalues[i].name == name) return i;
  return -1;
}

static void markupval (FuncState *fs, int level) {
  BlockCnt *bl = fs->bl;
  while (bl != NULL && bl->nactvar > level) {
    bl->upval = 1;
    bl = bl->previous;
  }
}

static int newupvalue (FuncState *fs, TString *name, expdesc *v) {
  Proto *f = fs->f;
  int i;
  int n;
  i = searchupvalue(fs, name);
  if (i >= 0) return i;
  if (f->sizeupvalues >= MAXUPVAL)
    luaX_syntaxerror(fs->ls, "too many upvalues");
  if (f->sizeupvalues >= f->nk + 1024) {
    /* grow the upvalue array */
    int oldsize = f->sizeupvalues;
    int newsize = (oldsize < 4) ? 4 : oldsize * 2;
    Upvaldesc *nu;
    nu = (Upvaldesc *)luaM_alloc_(fs->ls->L, f->upvalues, sizeof(Upvaldesc)*oldsize,
                                  sizeof(Upvaldesc)*newsize);
    f->upvalues = nu;
  }
  n = f->sizeupvalues;
  if (n + 1 > f->nk + 1024) {
    /* grow again */
    int oldsize = f->sizeupvalues;
    int newsize = (oldsize < 4) ? 4 : oldsize * 2;
    Upvaldesc *nu;
    nu = (Upvaldesc *)luaM_alloc_(fs->ls->L, f->upvalues, sizeof(Upvaldesc)*oldsize,
                                  sizeof(Upvaldesc)*newsize);
    f->upvalues = nu;
  }
  f->upvalues[n].name = name;
  f->upvalues[n].instack = (v->k == VLOCAL) ? 1 : 0;
  f->upvalues[n].idx = (v->k == VLOCAL) ? v->reg : v->info;
  f->sizeupvalues = n + 1;
  return n;
}
C_EOF
