/* ---------------------------------------------------------- expressions -- */

static void init_exp (expdesc *e, ExpKind k, int info) {
  e->k = k;
  e->t = NOJUMP;
  e->f = NOJUMP;
  e->info = info;
  e->reg = NOREG;
  e->idx = NOREG;
  e->nres = 0;
  e->isupval = 0;
}

static void freeexp (FuncState *fs, expdesc *e) {
  switch (e->k) {
    case VNONRELOC: case VLOCAL: case VCALL: case VVARARG: case VINDEXED:
      if (e->reg >= fs->nactvar)
        fs->freereg = e->reg;
      break;
    default: break;
  }
}

static void freeexps (FuncState *fs, expdesc *e1, expdesc *e2) {
  int r1 = (e1->k == VNONRELOC || e1->k == VLOCAL || e1->k == VCALL ||
            e1->k == VVARARG || e1->k == VINDEXED) ? e1->reg : MAXSTACK;
