  int pc;
  switch (e->k) {
    case VNIL: case VFALSE: {
      pc = newjump(fs);
      concat(fs, &e->f, pc);
      break;
    }
    case VTRUE: case VVOID:
      break;
    default: {
      exp2anyreg(fs, e);
      pc = codeAsBx(fs, OP_JUMPIFNOT, e->reg, 0);
      concat(fs, &e->f, pc);
      break;
    }
  }
}

static void goiftrue (FuncState *fs, expdesc *e) {
  int pc;
  switch (e->k) {
    case VNIL: case VFALSE:
