    case VTRUE: case VVOID: {
      pc = newjump(fs);
      concat(fs, &e->t, pc);
      break;
    }
    default: {
      exp2anyreg(fs, e);
      pc = codeAsBx(fs, OP_JUMPIF, e->reg, 0);
