/* ------------------------------------------------------- call emission -- */

typedef struct CallInfo_ {
  TString *name;
  int kind;
} CallInfo_;

static void emit_call (FuncState *fs, expdesc *f, int nargs, int nres,
                       CallInfo_ cs) {
  int func = f->reg;
  int pc;
  int c = (nres < 0) ? 0 : nres + 1;
  fs->freereg = func + 1 + nargs;
  checkstack(fs, nargs + 2);
  pc = codeABC(fs, OP_CALL, func, nargs + 1, c);
  if (pc < fs->f->sizecode) {
    fs->f->callsites[pc].name = cs.name;
    fs->f->callsites[pc].kind = (unsigned char)cs.kind;
  }
  init_exp(f, VCALL, pc);
  f->reg = func;
  f->nres = nres;
}

/* ---------------------------------------------------------- table index -- */

static void index_expr (FuncState *fs, expdesc *t, expdesc *k, TString *name,
                        int kind) {
  expdesc nt;
  (void)name;
  (void)kind;
  /* discharge the table to a register if needed */
  discharge(fs, t);
  if (t->k == VLOCAL || t->k == VNONRELOC || t->k == VUPVAL) {
    /* the table is a register (or an upvalue) */
    if (k->k == VK) {
      init_exp(&nt, (t->k == VUPVAL) ? VUPVALINDEXED : VINDEXED,
               (t->k == VUPVAL) ? t->info : t->reg);
      nt.idx = -1 - k->info;
      nt.isupval = (t->k == VUPVAL) ? 1 : 0;
    }
    else {
      int kreg;
      discharge(fs, k);
      exp2anyreg(fs, k);
      kreg = k->reg;
      init_exp(&nt, (t->k == VUPVAL) ? VUPVALINDEXED : VINDEXED,
               (t->k == VUPVAL) ? t->info : t->reg);
      nt.idx = kreg;
      nt.isupval = (t->k == VUPVAL) ? 1 : 0;
    }
  }
  else {
    /* the table must be in a register */
    exp2anyreg(fs, t);
    if (k->k == VK) {
      init_exp(&nt, VINDEXED, t->reg);
      nt.idx = -1 - k->info;
    }
    else {
      int kreg;
      exp2anyreg(fs, k);
      kreg = k->reg;
      init_exp(&nt, VINDEXED, t->reg);
      nt.idx = kreg;
    }
  }
  freeexp(fs, t);
  freeexp(fs, k);
  *t = nt;
}

/* ------------------------------------------------------------- parsing -- */

static void check (LexState *ls, int c) {
  if (ls->ttoken != c)
    error_expected(ls, c);
}

static int testnext (LexState *ls, int c) {
  if (ls->ttoken == c) {
    luaX_next(ls);
    return 1;
  }
  return 0;
}

static void checkmatch (LexState *ls, int what, int who, int line) {
  if (!testnext(ls, what)) {
    if (line == ls->linenumber)
      error_expected(ls, what);
    else {
      char buff[220];
      snprintf(buff, sizeof(buff), "%s expected (to close '%s' at line %d)",
               txtToken_(ls, what), txtToken_(ls, who), line);
      lexerror_(ls, buff, ls->ttoken);
    }
  }
}

static TString *str_checkname (LexState *ls) {
  TString *ts;
  check(ls, TK_NAME);
  ts = ls->seminfo.ts;
  luaX_next(ls);
  return ts;
}

static void codestring (FuncState *fs, expdesc *e, TString *ts) {
  init_exp(e, VK, stringK(fs, ts));
}

static void singlevar (LexState *ls, expdesc *var) {
  TString *varname = str_checkname(ls);
  FuncState *fs = ls->fs;
  expdesc key;
  if (singlevaraux(fs, varname, var, 1))
    return;
  codestring(fs, &key, varname);
  {
    expdesc env;
    singlevaraux(fs, ls->envn, &env, 1);
    if (env.k == VLOCAL) {
      init_exp(var, VINDEXED, env.reg);
      var->idx = -1 - key.info;
      var->isupval = 0;
    }
    else if (env.k == VUPVAL) {
      init_exp(var, VUPVALINDEXED, env.info);
      var->idx = -1 - key.info;
      var->isupval = 1;
    }
    else {
      init_exp(var, VNONRELOC, 0);
      codeABC(fs, OP_LOADNIL, fs->freereg, 0, 0);
      var->reg = fs->freereg;
      reserve(fs, 1);
    }
  }
}

/* -------------------------------------------------------- table fields -- */

static void recfield (LexState *ls, ConsControl *cc) {
  FuncState *fs = ls->fs;
  expdesc key, val;
  TString *name = NULL;
  int kind = 4;
  if (ls->ttoken == TK_NAME || ls->ttoken == '[') {
    if (ls->ttoken == TK_NAME) {
      name = str_checkname(ls);
      codestring(fs, &key, name);
    }
    else {
      luaX_next(ls);
      expr(ls, &key);
      checkmatch(ls, ']', '[', ls->linenumber);
      kind = 4;
    }
  }
  else {
    init_exp(&key, VK, intK(fs, cc->na));
    cc->na++;
    kind = 0;
  }
  check(ls, '=');
  luaX_next(ls);
  expr(ls, &val);
  addfield(fs, cc, &val, &key, kind, name);
}
C_EOF2
