  if (ls->ttoken != '}') {
    do {
      if (ls->ttoken == ']') {
        luaX_syntaxerror(ls, "unexpected symbol");
      }
      if (ls->ttoken == TK_NAME) {
        /* could be a named field or a positional value */
        int look = ls->lookahead;
        if (look == '=') {
          /* named field */
          TString *name = ls->seminfo.ts;
          expdesc key, val;
          luaX_next(ls);   /* skip the name */
          luaX_next(ls);   /* skip '=' */
          expr(ls, &val);
          codestring(fs, &key, name);
          addfield(fs, &cc, &val, &key, 1);
        }
        else {
          expdesc val;
          expr(ls, &val);
          {
            expdesc key;
            init_exp(&key, VK, 0);
            key.info = 0;
            addfield(fs, &cc, &val, &key, 0);
