  {
    Instruction i = fs->f->code[pc];
    int b = (cc.na > 0) ? (ceillog2_(cc.na) + 1) : 0;
    int c = (cc.nh > 0) ? (ceillog2_(cc.nh) + 1) : 0;
    if (b > 0xff) b = 0xff;
    if (c > 0xff) c = 0xff;
    fs->f->code[pc] = MAKE_OP(GET_OP(i), GET_A(i), b, c);
  }
  *t = cc.v;
}

static int ceillog2_ (int x) {
  int l = 0;
  unsigned int v = (unsigned int)x;
  if (v == 0) return 0;
  v--;
  while (v > 0) { v >>= 1; l++; }
  return l;
