/* --------------------------------------------------- table constructor -- */

typedef struct ConsControl {
  expdesc v;
  int nh;
  int na;
  int tostore;
  int blockidx;
  int lastmulti;
} ConsControl;

static void closelist (FuncState *fs, ConsControl *cc) {
  if (cc->tostore > 0) {
    codeABC(fs, OP_SETLIST, cc->v.reg, cc->tostore + 1, cc->blockidx + 1);
    cc->tostore = 0;
    cc->blockidx++;
    fs->freereg = cc->v.reg + 1;
  }
}

static void addfield (FuncState *fs, ConsControl *cc, expdesc *v, expdesc *k,
                      int kind) {
  if (kind == 0) {   /* positional field */
    int reg;
    if (cc->tostore == LFIELDS)
      closelist(fs, cc);
    reg = cc->v.reg + 1 + cc->tostore;
    fs->freereg = reg;
    if (v->k == VCALL || v->k == VVARARG) {
      /* multiple values: they fill the remaining positions */
      if (v->k == VCALL)
        setcallres(fs, v, -1);
      cc->tostore++;
      closelist(fs, cc);
      cc->lastmulti = 1;
      cc->na += 1;
      return;
    }
    exp2reg(fs, v, reg);
    cc->tostore++;
    fs->freereg = reg + 1;
    cc->na++;
  }
  else {   /* hash field */
    int reg;
    closelist(fs, cc);
    reg = cc->v.reg + 1;
    fs->freereg = reg;
    exp2reg(fs, v, reg);
    if (kind == 1) {   /* named field: the key is a string constant */
      codeABx(fs, OP_SETFIELD, cc->v.reg, -1 - k->info);
    }
    else if (k->k == VK) {
      codeABC(fs, OP_SETTABLE, cc->v.reg, reg, 0);
      /* hmm: the key must be in a register */
    }
    else {
      int kreg;
      discharge(fs, k);
      exp2anyreg(fs, k);
      kreg = k->reg;
      codeABC(fs, OP_SETTABLE, cc->v.reg, kreg, 0);
      /* hmm: the value register must be passed */
    }
    cc->nh++;
    fs->freereg = cc->v.reg + 1;
  }
}

static void table_constructor (LexState *ls, expdesc *t) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  ConsControl cc;
  int pc;
  cc.nh = 0;
  cc.na = 0;
  cc.tostore = 0;
  cc.blockidx = 0;
