/* ------------------------------------------------------- function body -- */

static void enterblock (FuncState *fs, BlockCnt *bl, int isloop) {
  bl->previous = fs->bl;
  bl->firstlabel = fs->nlabels;
  bl->firstgoto = fs->ngotos;
  bl->nactvar = fs->nactvar;
  bl->upval = 0;
  bl->insideloop = isloop ? 1 : (fs->bl ? fs->bl->insideloop : 0);
  fs->bl = bl;
}

static void leaveblock (FuncState *fs) {
  BlockCnt *bl = fs->bl;
  int i;
  /* resolve pending gotos that target labels in enclosing blocks */
  for (i = bl->firstgoto; i < fs->ngotos; i++) {
    if (!fs->gotos[i].resolved) {
      int j;
      for (j = fs->nlabels - 1; j >= 0; j--) {
        if (j < bl->firstlabel && fs->labels[j].name == fs->gotos[i].name) {
          /* the label is in an enclosing block: jump to it */
          if (bl->upval) {
            codeABC(fs, OP_CLOSE, bl->nactvar, 0, 0);
            fixjump(fs, fs->gotos[i].pc, fs->pc - 1);
          }
          else
            fixjump(fs, fs->gotos[i].pc, fs->labels[j].pc);
          fs->gotos[i].resolved = 1;
          break;
        }
      }
    }
  }
  /* emit a close instruction if the block has captured upvalues */
  if (bl->upval) {
    /* insert OP_CLOSE before the block end */
    codeABC(fs, OP_CLOSE, bl->nactvar, 0, 0);
  }
  removevars(fs, bl->nactvar);
  fs->nlabels = bl->firstlabel;
  fs->bl = bl->previous;
}

static void body (LexState *ls, expdesc *e, int ismethod, int line);

static void parlist (LexState *ls, FuncState *fs, int *nparams, int *isvararg) {
  FuncState *nfs = ls->fs;
  (void)fs;
  if (ls->ttoken != ')') {
    do {
      switch (ls->ttoken) {
        case TK_NAME: {
          TString *ts = str_checkname(ls);
          newlocalvar(ls, ts);
          (*nparams)++;
          break;
        }
        case TK_ELLIPSIS: {
          luaX_next(ls);
          newlocalvar(ls, luaS_newliteral(ls->L, "(*varargs)"));
          *isvararg = 1;
          break;
        }
        default: error_expected(ls, TK_NAME); break;
      }
    } while (!*isvararg && testnext(ls, ','));
  }
}

static void body (LexState *ls, expdesc *e, int ismethod, int line) {
  FuncState *fs = ls->fs;
  FuncState nfs;
  BlockCnt bl;
  int nparams = 0;
  int isvararg = 0;
  Proto *nf;
  /* create the new function */
  nfs.f = NULL;
  nfs.prev = fs;
  nfs.ls = ls;
  nfs.bl = NULL;
  nfs.nk = 0;
  nfs.nactvar = 0;
  nfs.freereg = 0;
  nfs.pc = 0;
  nfs.jpc = NOJUMP;
  nfs.needclose = 0;
  nfs.labels = NULL;
  nfs.nlabels = 0;
  nfs.labsize = 0;
  nfs.gotos = NULL;
  nfs.ngotos = 0;
  nfs.gotsize = 0;
  nf = (Proto *)luaM_alloc_(ls->L, NULL, 0, sizeof(Proto));
  memset(nf, 0, sizeof(Proto));
  nf->tt = LUA_VPROTO;
  nf->marked = 1;
  nf->source = ls->source;
  nf->linedefined = line;
  nf->lastlinedefined = 0;
  nf->numparams = 0;
  nf->is_vararg = 0;
  nf->maxstacksize = 0;
  nf->sizek = 0;
  nf->sizecode = 0;
  nfs.f = nf;
  ls->fs = &nfs;
  luaC_link(ls->L, (GCObject *)nf, LUA_VPROTO);
  /* parse the parameters */
  checkmatch(ls, '(', TK_FUNCTION, line);
  if (ismethod) {
    newlocalvar(ls, luaS_newliteral(ls->L, "self"));
    nparams++;
  }
  parlist(ls, &nfs, &nparams, &isvararg);
  checkmatch(ls, ')', '(', line);
  nf->numparams = nparams;
  nf->is_vararg = isvararg;
  /* the parameters occupy registers 0..nparams-1 */
  {
    int i;
    for (i = 0; i < nparams; i++) {
      nf->locvars[i].startpc = 0;
    }
    nfs.freereg = nparams;
  }
  /* parse the body */
  enterblock(&nfs, &bl, 0);
  statlist(ls);
  if (ls->ttoken != TK_END && ls->ttoken != TK_EOFS)
    error_expected(ls, TK_END);
  /* add an implicit return if needed */
  if (nfs.pc == 0 || GET_OP(nf->code[nfs.pc-1]) != OP_RETURN) {
    codeAB(&nfs, OP_RETURN, nparams + 1, 1);
  }
  leaveblock(&nfs);
  nf->lastlinedefined = ls->linenumber;
  /* transfer the proto to the outer function */
  {
    /* store the proto in the enclosing function's proto list */
    if (fs->f->sizep >= fs->f->sizecode) {
      /* grow */
    }
    if (fs->f->sizep <= fs->f->sizelocvars + 0) {
      int oldsize = fs->f->sizep;
      int newsize = (oldsize < 4) ? 4 : oldsize * 2;
      Proto **np;
      np = (Proto **)luaM_alloc_(ls->L, fs->f->p, sizeof(Proto*)*oldsize,
                                 sizeof(Proto*)*newsize);
      fs->f->p = np;
      fs->f->sizep = newsize;
    }
    fs->f->p[fs->f->npp++] = nf;
  }
  ls->fs = fs;
  /* emit OP_CLOSURE */
  {
    int bx = fs->f->npp - 1;
    if (bx > MAXARG_Bx)
      luaX_syntaxerror(ls, "too many nested functions");
    {
      int reg = fs->freereg;
      reserve(fs, 1);
      codeABx(fs, OP_CLOSURE, reg, bx);
      init_exp(e, VNONRELOC, 0);
      e->reg = reg;
      e->info = bx;
    }
  }
  /* check for unresolved gotos */
  {
    int i;
    for (i = 0; i < nfs.ngotos; i++) {
      if (!nfs.gotos[i].resolved) {
        char buff[220];
        snprintf(buff, sizeof(buff), "visible label '%s' not defined",
                 nfs.gotos[i].name ? nfs.gotos[i].name->contents : "?");
        lexerror_(ls, buff, 0);
      }
    }
  }
}
C_EOF2
