      break;
    case VUPVAL: {
      exp2anyreg(fs, e);
      codeABC(fs, OP_SETUPVAL, e->reg, var->info, 0);
      break;
    }
    case VINDEXED: {
      int src;
      exp2anyreg(fs, e);
      src = e->reg;
      if (var->idx >= 0)
        codeABC(fs, OP_SETTABLE, var->reg, var->idx, src);
