  else {
    explist(ls, &e, &nexps, &startreg);
    if (e.k == VCALL) {
      setcallres(fs, &e, -1);
      codeABC(fs, OP_RETURN, startreg, 0, needclose ? 1 : 0);
    }
    else if (e.k == VVARARG) {
      int n = 1;
      codeABx(fs, OP_VARARG, startreg, 0);
      codeABC(fs, OP_RETURN, startreg, 0, needclose ? 1 : 0);
      (void)n;
    }
    else {
      codeABC(fs, OP_RETURN, startreg, nexps + 1, needclose ? 1 : 0);
    }
    /* skip an optional semicolon */
    testnext(ls, ';');
  }
  /* everything after a return in this block is unreachable */
}

static void localfunc (LexState *ls, TString *name) {
  FuncState *fs = ls->fs;
  expdesc e;
  int reg;
  int freg;
  /* declare the local function name first */
  reg = fs->nactvar;
  newlocalvar(ls, name);
  freg = fs->freereg;
  body(ls, &e, 0, ls->linenumber);
  /* the closure is in e.reg: move it to the local's register */
  if (e.reg != reg)
    codeABC(fs, OP_MOVE, reg, e.reg, 0);
  fs->freereg = fs->nactvar;
}

static void funcstat (LexState *ls, int line, TString *name, expdesc *var, int ismethod) {
  FuncState *fs = ls->fs;
  expdesc e;
  body(ls, &e, ismethod, line);
  storevar(fs, var, &e);
  freeexp(fs, &e);
  fs->freereg = fs->nactvar;
}

/* -------------------------------------------------------------- labels -- */

static int gotolabel (FuncState *fs, TString *name) {
  int i;
  for (i = fs->nlabels - 1; i >= 0; i--)
    if (fs->labels[i].name == name) return i;
  return -1;
}

static void addlabel (FuncState *fs, TString *name, int pc, int line) {
  if (fs->nlabels >= fs->labsize) {
    int oldsize = fs->labsize;
    int newsize = (oldsize < 4) ? 4 : oldsize * 2;
    Labeldesc *nl = (Labeldesc *)luaM_alloc_(fs->ls->L, fs->labels,
                                             sizeof(Labeldesc)*oldsize,
                                             sizeof(Labeldesc)*newsize);
    fs->labels = nl;
    fs->labsize = newsize;
  }
  fs->labels[fs->nlabels].name = name;
  fs->labels[fs->nlabels].pc = pc;
  fs->labels[fs->nlabels].line = line;
  fs->labels[fs->nlabels].resolved = 0;
  fs->nlabels++;
}

static void addgoto (FuncState *fs, TString *name, int pc, int line) {
  if (fs->ngotos >= fs->gotsize) {
    int oldsize = fs->gotsize;
    int newsize = (oldsize < 4) ? 4 : oldsize * 2;
    Labeldesc *nl = (Labeldesc *)luaM_alloc_(fs->ls->L, fs->gotos,
                                             sizeof(Labeldesc)*oldsize,
                                             sizeof(Labeldesc)*newsize);
    fs->gotos = nl;
    fs->gotsize = newsize;
  }
  fs->gotos[fs->ngotos].name = name;
  fs->gotos[fs->ngotos].pc = pc;
  fs->gotos[fs->ngotos].line = line;
  fs->gotos[fs->ngotos].resolved = 0;
  fs->ngotos++;
}

static void labelstat (LexState *ls, TString *name, int line) {
  FuncState *fs = ls->fs;
  int i;
  (void)line;
  /* skip '::' */
  check(ls, TK_DBCOLON);
  luaX_next(ls);
  addlabel(fs, name, fs->pc, line);
  /* resolve pending gotos with this name */
  for (i = 0; i < fs->ngotos; i++) {
    if (!fs->gotos[i].resolved && fs->gotos[i].name == name) {
      fixjump(fs, fs->gotos[i].pc, fs->pc);
      fs->gotos[i].resolved = 1;
    }
  }
  check(ls, TK_DBCOLON);
  luaX_next(ls);
}

static void gotostat (LexState *ls, int line) {
  FuncState *fs = ls->fs;
  TString *name;
  int li;
  (void)line;
  name = str_checkname(ls);
  li = gotolabel(fs, name);
  if (li >= 0) {
    /* jump to the label */
    int jmp = newjump(fs);
    fixjump(fs, jmp, fs->labels[li].pc);
  }
  else {
    int jmp = newjump(fs);
    addgoto(fs, name, jmp, ls->linenumber);
  }
}
