/* -------------------------------------------------------- expressions --- */

static void simpleexp (LexState *ls, expdesc *v);
static void suffixedexp_ (LexState *ls, expdesc *v);

static void primaryexp (LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  switch (ls->ttoken) {
    case '(': {
      int line = ls->linenumber;
      luaX_next(ls);
      expr(ls, v);
      checkmatch(ls, ')', '(', line);
      /* a parenthesized expression is a single value */
      if (v->k == VCALL) setonerow(fs, v);
      else if (v->k == VVARARG) {
        codeABx(fs, OP_VARARG, fs->freereg, 2);
        v->k = VNONRELOC;
        v->reg = fs->freereg;
        reserve(fs, 1);
      }
      break;
    }
    case TK_NAME:
      singlevar(ls, v);
      break;
    default: {
      char buff[220];
      snprintf(buff, sizeof(buff), "unexpected symbol near %s",
               txtToken_(ls, ls->ttoken));
      lexerror_(ls, buff, ls->ttoken);
    }
  }
}

static void simpleexp (LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  switch (ls->ttoken) {
    case TK_NUMBER_FLT: {
      init_exp(v, VK, fltK(fs, ls->seminfo.r));
      luaX_next(ls);
      break;
    }
    case TK_NUMBER_INT: {
      init_exp(v, VK, intK(fs, ls->seminfo.i));
      luaX_next(ls);
      break;
    }
    case TK_STRING: {
      codestring(fs, v, ls->seminfo.ts);
      luaX_next(ls);
      break;
    }
    case TK_NIL: {
      init_exp(v, VNIL, 0);
      luaX_next(ls);
      break;
    }
    case TK_TRUE: {
      init_exp(v, VTRUE, 0);
      luaX_next(ls);
      break;
    }
    case TK_FALSE: {
      init_exp(v, VFALSE, 0);
      luaX_next(ls);
      break;
    }
    case TK_DOTS: {
      if (!fs->f->is_vararg)
        lexerror_(ls, "cannot use '...' outside a vararg function", TK_DOTS);
      init_exp(v, VVARARG, 0);
      v->nres = -1;
      luaX_next(ls);
      break;
    }
    case '{':
      table_constructor(ls, v);
      break;
    case TK_FUNCTION: {
      int line = ls->linenumber;
      luaX_next(ls);
      body(ls, v, 0, line);
      return;
    }
    default:
      primaryexp(ls, v);
      return;
  }
}

/*
** parse a suffixed expression (index, call)
*/
static void suffixedexp_ (LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  for (;;) {
    switch (ls->ttoken) {
      case '.': {
        TString *ts;
        expdesc key, t;
        luaX_next(ls);
        ts = str_checkname(ls);
        t = *v;
        codestring(fs, &key, ts);
        index_expr(fs, &t, &key, ts, 4);
        *v = t;
        break;
      }
      case '[': {
        expdesc key, t;
        int line = ls->linenumber;
        luaX_next(ls);
        expr(ls, &key);
