      v->nres = -1;
      luaX_next(ls);
      break;
    }
    case '{':
      table_constructor(ls, v);
      break;
    case TK_FUNCTION: {
      int line = ls->linenumber;
      luaX_next(ls);
      body(ls, v, 0, line);
      return;
