/*
** parse a suffixed expression (index, call)
*/
static void suffixedexp_ (LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  for (;;) {
    switch (ls->ttoken) {
      case '.': {
        TString *ts;
        expdesc key, t;
        luaX_next(ls);
        ts = str_checkname(ls);
        t = *v;
        codestring(fs, &key, ts);
        index_expr(fs, &t, &key, ts, 4);
        *v = t;
        break;
      }
      case '[': {
        expdesc key, t;
        int line = ls->linenumber;
        luaX_next(ls);
        expr(ls, &key);
        checkmatch(ls, ']', '[', line);
        t = *v;
        index_expr(fs, &t, &key, NULL, 4);
        *v = t;
        break;
      }
      case ':': {
        TString *ts;
        expdesc key, t;
        int r;
        int nargs = 0;
        int selfmulti = 0;
        luaX_next(ls);
        ts = str_checkname(ls);
        /* the receiver must be in a register; the method in r and self in r+1 */
        r = fs->freereg;
        reserve(fs, 2);
        fs->freereg = r + 2;
        t = *v;
        exp2reg(fs, &t, r);
        codestring(fs, &key, ts);
        codeABC(fs, OP_SELF, r, r, key.info);
        fs->freereg = r + 2;
        /* parse the arguments into registers r+2, r+3, ... */
        nargs = parse_args_(ls, r + 2, &selfmulti);
        emit_call_(fs, r, nargs, 1, ts, 5);
        init_exp(v, VCALL, fs->pc - 1);
        v->reg = r;
        v->nres = 1;
        return;
      }
      case '(': case TK_STRING: case '{': {
        int r;
        int nargs = 0;
        int multi = 0;
        /* the function must be in a register */
        {
          int rr = fs->freereg;
          reserve(fs, 1);
          fs->freereg = rr + 1;
          {
            expdesc t = *v;
            exp2reg(fs, &t, rr);
          }
          r = rr;
        }
        {
          CallInfo_ cs;
          cs.name = NULL;
          cs.kind = 0;
          nargs = parse_args_(ls, r + 1, &multi);
          emit_call_(fs, r, nargs, multi ? -1 : 1, cs.name, cs.kind);
          init_exp(v, VCALL, fs->pc - 1);
          v->reg = r;
          v->nres = 1;
        }
        return;
      }
      default:
        return;
    }
  }
}

/*
** parse the arguments of a function call, placing them in consecutive
** registers starting at 'first'. Returns the number of arguments
** (or -1 if the last argument produces multiple values).
*/
static int parse_args_ (LexState *ls, int first, int *multi) {
  FuncState *fs = ls->fs;
  int n = 0;
  *multi = 0;
  if (ls->ttoken == '(') {
    int line = ls->linenumber;
    luaX_next(ls);
    if (ls->ttoken != ')') {
      do {
        expdesc arg;
        int last = 0;
        expr(ls, &arg);
        discharge(fs, &arg);
        if (ls->ttoken == ',') last = 0;
        else last = 1;
        if (arg.k == VCALL) {
          if (last) {
            setcallres(fs, &arg, -1);
            *multi = 1;
          }
          else setcallres(fs, &arg, 1);
          /* the results are in consecutive registers starting at arg.reg */
          if (arg.reg != first + n) {
            /* move them (one value at most for non-last args) */
            codeABC(fs, OP_MOVE, first + n, arg.reg, 0);
          }
          n += 1;
          fs->freereg = first + n;
        }
        else if (arg.k == VVARARG) {
          if (last) {
            codeABx(fs, OP_VARARG, first + n, 0);
            *multi = 1;
            n += 1;
            fs->freereg = first + n;
          }
          else {
            codeABx(fs, OP_VARARG, first + n, 2);
            n += 1;
            fs->freereg = first + n;
          }
        }
        else {
          exp2reg(fs, &arg, first + n);
          n += 1;
          fs->freereg = first + n;
        }
      } while (testnext(ls, ','));
    }
    checkmatch(ls, ')', '(', line);
  }
  else if (ls->ttoken == TK_STRING) {
    codestring(fs, NULL, ls->seminfo.ts);
    luaX_next(ls);
    n = 1;
    fs->freereg = first + 1;
  }
  else if (ls->ttoken == '{') {
    expdesc arg;
    table_constructor(ls, &arg);
    exp2reg(fs, &arg, first);
    n = 1;
    fs->freereg = first + 1;
  }
  else
    error_expected(ls, TK_NAME);
  return n;
}
