/*
** parse a subexpression with the given priority limit
*/
static void subexpr (LexState *ls, expdesc *v, int limit) {
  FuncState *fs = ls->fs;
  int op;
  int line = ls->linenumber;
  enterlevel_(ls);
  simpleexp(ls, v);
  while ((op = getbinop(ls->ttoken)) != OPR_NOBINOPR &&
         priority[op][0] > limit) {
    expdesc v2;
    luaX_next(ls);   /* skip the operator */
    if (op == OPR_AND || op == OPR_OR) {
      code_andor(fs, v, op, &v2);
      subexpr(ls, &v2, priority[op][1] - 1);
      code_andor2(fs, v, op, &v2);
    }
    else if (op == OPR_CONCAT) {
      subexpr(ls, &v2, priority[op][1] - 1);
      codeconcat(fs, v, v, &v2);
    }
    else if (op == OPR_EQ || op == OPR_NE || op == OPR_LT || op == OPR_LE ||
             op == OPR_GT || op == OPR_GE) {
      subexpr(ls, &v2, priority[op][1]);
      codecompare(fs, v, op, v, &v2);
    }
    else {
      /* unary operators handled elsewhere */
      subexpr(ls, &v2, priority[op][1]);
      codearith(fs, v, op, v, &v2);
    }
  }
  leavelevel_(ls);
}

static void enterlevel_ (LexState *ls) {
  (void)ls;
}

static void leavelevel_ (LexState *ls) {
  (void)ls;
}

static void code_andor2 (FuncState *fs, expdesc *v, int op, expdesc *v2) {
  (void)fs; (void)op;
  *v = *v2;
}

static void expr (LexState *ls, expdesc *v) {
  subexpr(ls, v, 0);
}

/*
** parse a unary expression
*/
static void subexpr_unary (LexState *ls, expdesc *v, int limit);

static int explist (LexState *ls, expdesc *v, int *nexps, int *startreg) {
  FuncState *fs = ls->fs;
  int n = 1;
  expr(ls, v);
  discharge(fs, v);
  if (v->k == VCALL) {
    setcallres(fs, v, 1);
    fs->freereg = v->reg + 1;
  }
  else if (v->k == VVARARG) {
    codeABx(fs, OP_VARARG, fs->freereg, 2);
    v->k = VNONRELOC;
    v->reg = fs->freereg;
    reserve(fs, 1);
    fs->freereg = v->reg + 1;
  }
  else {
    int r = fs->freereg;
    reserve(fs, 1);
    exp2reg(fs, v, r);
    fs->freereg = r + 1;
  }
  *startreg = v->reg;
  while (testnext(ls, ',')) {
    int target = fs->freereg;
    expr(ls, v);
    discharge(fs, v);
    if (v->k == VCALL) {
      setcallres(fs, v, 1);
      fs->freereg = v->reg + 1;
    }
    else if (v->k == VVARARG) {
      codeABx(fs, OP_VARARG, target, 2);
      v->k = VNONRELOC;
      v->reg = target;
      fs->freereg = target + 1;
    }
    else {
      exp2reg(fs, v, target);
      fs->freereg = target + 1;
    }
    n++;
  }
  *nexps = n;
  return n;
}

static int block_follow_ (LexState *ls) {
  switch (ls->ttoken) {
    case TK_ELSE: case TK_ELSEIF: case TK_END: case TK_EOFS:
    case TK_UNTIL:
      return 1;
    default: return 0;
  }
}

static void statement (LexState *ls) {
  int line = ls->linenumber;
  FuncState *fs = ls->fs;
  fs->freereg = fs->nactvar;   /* all temporaries are free at a statement boundary */
  switch (ls->ttoken) {
    case ';': {
      luaX_next(ls);
      break;
    }
    case TK_IF: {
      ifstat(ls, line);
      break;
    }
    case TK_WHILE: {
      whilestat(ls, line);
      break;
    }
    case TK_DO: {
      luaX_next(ls);
      block(ls);
      checkmatch(ls, TK_END, TK_DO, line);
      break;
    }
    case TK_FOR: {
      forstat(ls, line);
      break;
    }
    case TK_REPEAT: {
      repeatstat(ls, line);
      break;
    }
    case TK_FUNCTION: {
      TString *name;
      expdesc var;
      int ismethod = 0;
      luaX_next(ls);
      name = str_checkname(ls);
      singlevar_(ls, name, &var);
      while (ls->ttoken == '.') {
        expdesc key;
        expdesc t;
        TString *ts;
        luaX_next(ls);
        ts = str_checkname(ls);
        t = var;
        codestring(fs, &key, ts);
        index_expr(fs, &t, &key, ts, 4);
        var = t;
      }
      if (ls->ttoken == ':') {
        ismethod = 1;
        {
          expdesc key;
          expdesc t;
          TString *ts;
          luaX_next(ls);
          ts = str_checkname(ls);
          t = var;
          codestring(fs, &key, ts);
          index_expr(fs, &t, &key, ts, 5);
          var = t;
        }
      }
      funcstat(ls, line, name, &var, ismethod);
      break;
    }
    case TK_LOCAL: {
      luaX_next(ls);
      if (testnext(ls, TK_FUNCTION)) {
        TString *name = str_checkname(ls);
        localfunc(ls, name);
      }
      else {
        TString *names[MAXVARS];
        int nvars = 0;
        int nexps;
        int startreg;
        expdesc e;
        do {
          if (nvars >= MAXVARS)
            luaX_syntaxerror(ls, "too many local variables");
          names[nvars++] = str_checkname(ls);
        } while (testnext(ls, ','));
        if (testnext(ls, '=')) {
          int base;
          int i;
          explist(ls, &e, &nexps, &startreg);
          adjust_assign(ls, nvars, nexps, &e);
          base = fs->nactvar;
          for (i = nvars - 1; i >= 0; i--) {
            int src = startreg + i;
            int dst = base + i;
            if (src != dst && i < nexps)
              codeABC(fs, OP_MOVE, dst, src, 0);
            newlocalvar(ls, names[i]);
          }
          /* the extra values (nil) are already in registers */
          fs->freereg = fs->nactvar;
        }
        else {
          int base = fs->nactvar;
          int i;
          for (i = nvars - 1; i >= 0; i--)
            newlocalvar(ls, names[i]);
          codeABC(fs, OP_LOADNIL, base, nvars - 1, 0);
          fs->freereg = fs->nactvar;
        }
      }
      break;
    }
    case TK_DBCOLON: {
      TString *name = ls->seminfo.ts;
      labelstat(ls, name, line);
      break;
    }
    case TK_GOTO: {
      luaX_next(ls);
      gotostat(ls, line);
      break;
    }
    case TK_RETURN: {
      retstat(ls, line);
      break;
    }
    case TK_BREAK: {
      breakstat(ls);
      break;
    }
    default: {
      exprstat(ls);
      break;
    }
  }
}

static void singlevar_ (LexState *ls, TString *name, expdesc *var) {
  FuncState *fs = ls->fs;
  expdesc key;
  if (singlevaraux(fs, name, var, 1))
    return;
  codestring(fs, &key, name);
  {
    expdesc env;
    singlevaraux(fs, ls->envn, &env, 1);
    if (env.k == VLOCAL) {
      init_exp(var, VINDEXED, env.reg);
      var->idx = -1 - key.info;
    }
    else if (env.k == VUPVAL) {
      init_exp(var, VUPVALINDEXED, env.info);
      var->idx = -1 - key.info;
      var->isupval = 1;
    }
    else {
      init_exp(var, VNONRELOC, 0);
      codeABC(fs, OP_LOADNIL, fs->freereg, 0, 0);
      var->reg = fs->freereg;
      reserve(fs, 1);
    }
  }
}

/* -------------------------------------------------------- main parsing -- */

static void close_func (FuncState *fs) {
  Proto *f = fs->f;
  /* the code arrays are already sized; adjust the counts */
  f->sizecode = fs->pc;
  /* the constants: f->sizek is the capacity; set it to the used count */
  f->sizek = fs->nk;
  f->locvars = NULL;
  (void)f;
}

struct Proto *luaY_parse (lua_State *L, const char *z, size_t size,
                          TString *chunkname, const char *mode) {
  LexState ls;
  FuncState fs;
  BlockCnt bl;
  Proto *f;
  (void)mode;
  memset(&ls, 0, sizeof(ls));
  luaX_setinput(L, &ls, chunkname, z, size);
  ls.envn = luaS_new(L, "_ENV");
  f = (Proto *)luaM_alloc_(L, NULL, 0, sizeof(Proto));
  memset(f, 0, sizeof(Proto));
  f->tt = LUA_VPROTO;
  f->marked = 1;
  f->source = chunkname;
  f->linedefined = 0;
  f->lastlinedefined = 0;
  f->is_vararg = 1;
  f->numparams = 0;
  memset(&fs, 0, sizeof(fs));
  fs.f = f;
  fs.prev = NULL;
  fs.ls = &ls;
  fs.bl = NULL;
  fs.pc = 0;
  fs.nk = 0;
  fs.nactvar = 0;
  fs.freereg = 0;
  fs.jpc = NOJUMP;
  fs.needclose = 0;
  ls.fs = &fs;
  enterblock(&fs, &bl, 0);
  luaX_next(&ls);
  statlist(&ls);
  check(&ls, TK_EOFS);
  /* an implicit return at the end */
  codeABC(&fs, OP_RETURN, 0, 1, 0);
  leaveblock(&fs);
  close_func(&fs);
  /* create the _ENV upvalue */
  {
    expdesc e;
    e.k = VLOCAL;
    e.reg = 0;
    newupvalue(&fs, ls.envn, &e);
    f->upvalues[0].instack = 0;
    f->upvalues[0].idx = 0;
  }
  return f;
}

int luaY_parser (lua_State *L, const char *z, size_t size, TString *chunkname,
                  const char *mode) {
  struct Proto *p = luaY_parse(L, z, size, chunkname, mode);
  if (p == NULL) return LUA_ERRSYNTAX;
  /* create the closure and push it */
  {
    Closure *cl = luaF_newLclosure(L, p->sizeupvalues);
    int i;
    cl->f.p = p;
    for (i = 0; i < p->sizeupvalues; i++) {
      cl->upvals[i] = NULL;
    }
    /* the _ENV upvalue holds the globals table */
    {
      UpVal *uv = (UpVal *)luaM_new(L, UpVal);
      Table *gt = luaG_globals(L);
      sethvalue(&uv->value, gt);
      uv->v = &uv->value;
      uv->chain = NULL;
      luaC_link(L, (GCObject *)uv, LUA_VUPVAL);
      cl->upvals[0] = uv;
    }
    luaD_checkstack(L, 1);
    setclvalue(L->stack + L->top, cl);
    L->top++;
  }
  return LUA_OK;
}
