{"command": "cd /workspace/src && cat > lbaselib.c <<'C_EOF'
/* base library */
#include "lua.h"
#include "lobject.h"
#include "lstate.h"
#include "lvm.h"
#include "ltable.h"
#include "lstring.h"
#include "ldebug.h"
#include "lapi.h"
#include "lfunc.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

static int luaB_print (lua_State *L) {
  int n = lua_gettop(L);
  int i;
  for (i = 1; i <= n; i++) {
    size_t l;
    const char *s = lua_tolstring(L, i, &l);
    if (i > 1) fputc('\t', stdout);
    if (s != NULL) fwrite(s, 1, l, stdout);
  }
  fputc('\n', stdout);
  return 0;
}

static int luaB_error (lua_State *L) {
  int level = (int)lua_tointegerx(L, 2, NULL);
  if (level == 0) level = 1;
  lua_settop(L, 1);
  if (lua_isstring(L, 1) && level > 0) {
    const char *where = luaG_where_(L, level);
    if (where != NULL && *where != '\0') {
      size_t l;
      const char *m = lua_tolstring(L, 1, &l);
      char *b = (char *)luaM_alloc_(L, NULL, 0, strlen(where) + l + 1);
      size_t wl = strlen(where);
      memcpy(b, where, wl);
      memcpy(b + wl, m, l);
      setsvalue2s(L, L->stack + L->top - 1, luaS_newlstr(L, b, wl + l));
      L->top = L->top;   /* keep */
      luaM_free(L, b, wl + l + 1);
    }
  }
  return lua_error(L);
}

static int luaB_tostring (lua_State *L) {
  size_t l;
  const char *s = lua_tolstring(L, 1, &l);
  if (s == NULL) {
    /* not a string or number: use the type name */
    TValue *o = api_index_(L, 1);
    if (o == NULL) lua_pushliteral(L, "nil");
    else if (ttisnil(o)) lua_pushliteral(L, "nil");
    else {
      char buff[64];
      snprintf(buff, sizeof(buff), "%s: %p", luaO_typename(o), (void *)gcvalue(o));
      lua_pushstring(L, buff);
    }
  }
  else lua_pushlstring(L, s, l);
  return 1;
}

static int luaB_tonumber (lua_State *L) {
  if (lua_isnoneornil(L, 2)) {
    TValue *o = api_index_(L, 1);
    if (o == NULL) { lua_pushnil(L); return 1; }
    if (ttisnumber(o)) { lua_pushnil(L); lua_pop(L, 1); lua_pushvalue(L, -1); return 1; }
    if (ttisstring(o)) {
      TValue n;
      char buf[64];
      size_t l = tsvalue(o)->length;
      if (l < sizeof(buf)) {
        memcpy(buf, tsvalue(o)->contents, l);
        buf[l] = '\0';
        if (luaO_str2num(buf, l, &n) != 0) {
          lua_pushnil(L);
          if (ttisinteger(&n)) { lua_pop(L,1); lua_pushinteger(L, ivalue(&n)); }
          else { lua_pop(L,1); lua_pushnumber(L, fltvalue(&n)); }
          return 1;
        }
      }
    }
    lua_pushnil(L);
    return 1;
  }
  else {
    lua_Integer base = lua_tointeger(L, 2);
    const char *s = lua_tolstring(L, 1, NULL);
    if (s == NULL || base < 2 || base > 36) {
      lua_pushnil(L);
      return 1;
    }
    {
      lua_Integer n = 0;
      int neg = 0;
      const char *p = s;
      while (*p == ' ' || *p == '\t' || *p == '\n') p++;
      if (*p == '-' || *p == '+') { neg = (*p == '-'); p++; }
      for (; *p != '\0'; p++) {
        int d;
        if (*p >= '0' && *p <= '9') d = *p - '0';
        else if (*p >= 'a' && *p <= 'z') d = *p - 'a' + 10;
        else if (*p >= 'A' && *p <= 'Z') d = *p - 'A' + 10;
        else { lua_pushnil(L); return 1; }
        if (d >= base) { lua_pushnil(L); return 1; }
        n = n * base + d;
      }
      lua_pushinteger(L, neg ? -n : n);
      return 1;
    }
  }
}

static int luaB_type (lua_State *L) {
  lua_pushstring(L, lua_typename(L, lua_type(L, 1)));
  return 1;
}

static int luaB_len (lua_State *L) {
  TValue *o = api_index_(L, 1);
  TValue res;
  if (o == NULL) luaG_typeerror(L, &luaO_absentkey, "get length of");
  luaV_objlen(L, &res, o);
  setobj2s(L->stack + L->top - 1, &res);
  return 1;
}

static int luaB_next (lua_State *L) {
  TValue *t = api_index_(L, 1);
  TValue *k = L->stack + L->top - 1;
  if (t == NULL || !ttistable(t))
    luaG_runerror(L, "table expected");
  if (luaH_next(L, hvalue(t), k))
    return 2;
  else {
    setnilvalue(k);
    return 1;
  }
}

static int luaB_pairs (lua_State *L) {
  TValue *t = api_index_(L, 1);
  const TValue *tm;
  if (t == NULL) return 0;
  if (ttistable(t)) {
    tm = luaT_gettmbyobj(L, t, TM_PAIRS);
    if (ttisnil(tm)) {
      /* the standard pairs */
      lua_pushcfunction(L, luaB_next);
      lua_pushvalue(L, 1);
      lua_pushnil(L);
      return 3;
    }
  }
  else tm = luaT_gettmbyobj(L, t, TM_PAIRS);
  if (!ttisnil(tm)) {
    /* call the metamethod */
    int oldtop = L->top;
    luaT_callTMres(L, tm, t, t, L->stack + L->top);
    L->top++;
    return 3;   /* hmm */
  }
  return 0;
}

static int luaB_ipairsaux (lua_State *L) {
  lua_Integer i = lua_tointegerx(L, 2, NULL) + 1;
  lua_pushinteger(L, i);
  lua_rawgeti(L, 1, i);
  return (ttisnil(L->stack + L->top - 1)) ? 1 : 2;
}

static int luaB_ipairs (lua_State *L) {
  lua_pushcfunction(L, luaB_ipairsaux);
  lua_pushvalue(L, 1);
  lua_pushinteger(L, 0);
  return 3;
}

static int luaB_pcall (lua_State *L) {
  int status;
  int n = lua_gettop(L);
  CallInfo *ci = L->ci;
  int oldtop = (int)((L->stack + L->top) - (L->stack + ci->func + 1));
  int funcidx = (int)((L->stack + L->top) - n - L->stack - ci->func - 1) + 1;
  (void)funcidx;
  status = do_pcall_(L, n - 1, LUA_MULTRET, 0);
  lua_pushboolean(L, status == LUA_OK);
  lua_insert(L, 1);
  return lua_gettop(L);
}

static int luaB_xpcall (lua_State *L) {
  int status;
  int n = lua_gettop(L);
  CallInfo *ci = L->ci;
  int ef;
  status = do_pcall_(L, n - 2, LUA_MULTRET, ef);
  (void)ci;
  lua_pushboolean(L, status == LUA_OK);
  lua_insert(L, 1);
  return lua_gettop(L);
}

static int luaB_select (lua_State *L) {
  int n = lua_gettop(L);
  lua_Integer i = lua_tointegerx(L, 1, NULL);
  if (i < 0) i = n + i;
  else if (i > n) i = n;
  if (i < 1)
    luaL_argerror_(L, 1, "index out of range");
  return (int)(n - (int)i);
}

static int luaB_rawget (lua_State *L) {
  TValue *t = api_index_(L, 1);
  TValue *k = L->stack + L->top - 1;
  const TValue *p;
  if (t == NULL || !ttistable(t)) return 0;
  p = luaH_get(L, hvalue(t), k);
  if (ttisnil(p)) setnilvalue(k);
  else setobj2s(k, p);
  return 1;
}

static int luaB_rawset (lua_State *L) {
  TValue *t = api_index_(L, 1);
  TValue *k = L->stack + L->top - 2;
  TValue *v = L->stack + L->top - 1;
  if (t == NULL || !ttistable(t)) return 0;
  {
    TValue *p = luaH_set(L, hvalue(t), k);
    if (ttisnil(v)) setnilvalue(p);
    else setobj2t(p, v);
  }
  L->top -= 2;
  return 0;
}

static int luaB_rawequal (lua_State *L) {
  TValue *o1 = api_index_(L, 1);
  TValue *o2 = api_index_(L, 2);
  lua_pushboolean(L, (o1 != NULL && o2 != NULL) ? luaV_rawequalobj(o1, o2) : 0);
  return 1;
}

static int luaB_rawlen (lua_State *L) {
  TValue *o = api_index_(L, 1);
  if (o == NULL) return 0;
  if (ttisstring(o)) lua_pushinteger(L, (lua_Integer)tsvalue(o)->length);
  else if (ttistable(o)) lua_pushinteger(L, luaH_getn(L, hvalue(o)));
  else if (ttisudata(o)) lua_pushinteger(L, (lua_Integer)uvalue(o)->len);
  else lua_pushnil(L);
  return 1;
}

static int luaB_setmetatable (lua_State *L) {
  TValue *t = api_index_(L, 1);
  TValue *mt = L->stack + L->top - 1;
  Table *m = NULL;
  if (t == NULL) return 0;
  if (!ttistable(t) && !ttisudata(t))
    luaG_runerror(L, "nil or table expected");
  if (!ttisnil(mt)) {
    if (!ttistable(mt))
      luaG_runerror(L, "nil or table expected");
    m = hvalue(mt);
    if (m != NULL) {
      const TValue *v = luaH_getshortstr(L, m, "__metatable");
      if (!ttisnil(v))
        luaG_runerror(L, "cannot change a protected metatable");
    }
  }
  if (ttistable(t)) hvalue(t)->metatable = m;
  else uvalue(t)->metatable = m;
  L->top--;
  return 1;
}

static int luaB_getmetatable (lua_State *L) {
  TValue *t = api_index_(L, 1);
  Table *m = NULL;
  if (t != NULL) {
    if (ttistable(t)) m = hvalue(t)->metatable;
    else if (ttisudata(t)) m = uvalue(t)->metatable;
  }
  if (m != NULL) {
    TValue v;
    sethvalue(&v, m);
    setobj2s(L->stack + L->top, &v);
    L->top++;
  }
  else lua_pushnil(L);
  return 1;
}

static int luaB_assert (lua_State *L) {
  if (l_isfalse(api_index_(L, 1))) {
    if (lua_gettop(L) > 1)
      return lua_error(L);   /* the message is on top */
    else {
      lua_pushliteral(L, "assertion failed!");
      return lua_error(L);
    }
  }
  return lua_gettop(L);
}

static int luaB_collectgarbage (lua_State *L) {
  static const char *const opts[] = { "collect", "stop", "restart", "count",
    "step", "setpause", "setstepmul", "isrunning", "incremental", "generational", NULL };
  int o = luaL_checkoption_(L, 1, "collect", opts);
  switch (o) {
    case 0: { luaC_fullgc(L, 0); lua_pushinteger(L, 0); return 1; }
    case 1: G(L)->gcrunning = 0; return 0;
    case 2: G(L)->gcrunning = 1; return 0;
    case 3: {
      lua_pushnumber(L, (lua_Number)(G(L)->totalbytes / 1024.0));
      return 1;
    }
    case 7: lua_pushboolean(L, G(L)->gcrunning); return 1;
    default: return 0;
