  lua_settop(L, 1);
  if (loadfile_(L, fname) != LUA_OK)
    return lua_error(L);
  lua_call(L, 0, LUA_MULTRET);
  return lua_gettop(L) - 1;
}

static int luaB_load (lua_State *L) {
