  size_t l;
  const char *s = lua_tolstring(L, 1, &l);
  const char *chunkname = luaL_optstring_(L, 2, s ? "=(load)" : "=(load)");
  int status;
  if (s == NULL) return 0;
  status = luaL_loadbufferx_(L, s, l, chunkname, NULL);
  if (status != LUA_OK) {
    lua_pushnil(L);
    lua_insert(L, -2);
    return 2;
  }
  return 1;
}

static const luaL_Reg base_funcs[] = {
  { "print", luaB_print },
  { "error", luaB_error },
  { "tostring", luaB_tostring },
  { "tonumber", luaB_tonumber },
  { "type", luaB_type },
  { "len", luaB_len },
  { "next", luaB_next },
  { "pairs", luaB_pairs },
  { "ipairs", luaB_ipairs },
  { "pcall", luaB_pcall },
  { "xpcall", luaB_xpcall },
  { "select", luaB_select },
  { "rawget", luaB_rawget },
  { "rawset", luaB_rawset },
  { "rawequal", luaB_rawequal },
  { "rawlen", luaB_rawlen },
  { "setmetatable", luaB_setmetatable },
  { "getmetatable", luaB_getmetatable },
  { "assert", luaB_assert },
  { "collectgarbage", luaB_collectgarbage },
  { "dofile", luaB_dofile },
  { "load", luaB_load },
