void luaopen_base (lua_State *L) {
  Table *gt = luaG_globals(L);
  int i;
  for (i = 0; base_funcs[i].name != NULL; i++) {
    TValue v;
    TString *name = luaS_new(L, base_funcs[i].name);
    setclvalue(&v, NULL);
