  if (ttisstring(o)) lua_pushinteger(L, (lua_Integer)tsvalue(o)->length);
  else if (ttistable(o)) lua_pushinteger(L, luaH_getn(L, hvalue(o)));
  else if (ttisudata(o)) lua_pushinteger(L, (lua_Integer)uvalue(o)->len);
  else lua_pushnil(L);
  return 1;
}

static int luaB_setmetatable (lua_State *L) {
  TValue *t = api_index_(L, 1);
  TValue *mt = L->stack + L->top - 1;
  Table *m = NULL;
  if (t == NULL) return 0;
  if (!ttistable(t) && !ttisudata(t))
    luaG_runerror(L, "nil or table expected");
  if (!ttisnil(mt)) {
    if (!ttistable(mt))
      luaG_runerror(L, "nil or table expected");
    m = hvalue(mt);
    if (m != NULL) {
      const TValue *v = luaH_getshortstr(L, m, "__metatable");
      if (!ttisnil(v))
        luaG_runerror(L, "cannot change a protected metatable");
    }
  }
  if (ttistable(t)) hvalue(t)->metatable = m;
  else uvalue(t)->metatable = m;
  L->top--;
  return 1;
}

static int luaB_getmetatable (lua_State *L) {
  TValue *t = api_index_(L, 1);
  Table *m = NULL;
  if (t != NULL) {
    if (ttistable(t)) m = hvalue(t)->metatable;
    else if (ttisudata(t)) m = uvalue(t)->metatable;
  }
  if (m != NULL) {
    TValue v;
    sethvalue(&v, m);
    setobj2s(L->stack + L->top, &v);
    L->top++;
  }
  else lua_pushnil(L);
  return 1;
}

static int luaB_assert (lua_State *L) {
  if (l_isfalse(api_index_(L, 1))) {
    if (lua_gettop(L) > 1)
      return lua_error(L);   /* the message is on top */
    else {
      lua_pushliteral(L, "assertion failed!");
      return lua_error(L);
    }
  }
  return lua_gettop(L);
}

static int luaB_collectgarbage (lua_State *L) {
  static const char *const opts[] = { "collect", "stop", "restart", "count",
    "step", "setpause", "setstepmul", "isrunning", "incremental", "generational", NULL };
  int o = luaL_checkoption_(L, 1, "collect", opts);
  switch (o) {
    case 0: { luaC_fullgc(L, 0); lua_pushinteger(L, 0); return 1; }
    case 1: G(L)->gcrunning = 0; return 0;
    case 2: G(L)->gcrunning = 1; return 0;
    case 3: {
      lua_pushnumber(L, (lua_Number)(G(L)->totalbytes / 1024.0));
      return 1;
    }
    case 7: lua_pushboolean(L, G(L)->gcrunning); return 1;
    default: return 0;
