static int luaB_dofile (lua_State *L) {
  const char *fname = luaL_optstring_(L, 1, NULL);
  lua_settop(L, 1);
  if (loadfile_(L, fname) != LUA_OK)
    return lua_error(L);
  lua_call(L, 0, LUA_MULTRET);
  return lua_gettop(L) - 1;
}

static int luaB_load (lua_State *L) {
  /* minimal: load a string chunk */
  size_t l;
  const char *s = lua_tolstring(L, 1, &l);
  const char *chunkname = luaL_optstring_(L, 2, s ? "=(load)" : "=(load)");
  int status;
  if (s == NULL) return 0;
  status = luaL_loadbufferx_(L, s, l, chunkname, NULL);
  if (status != LUA_OK) {
    lua_pushnil(L);
    lua_insert(L, -2);
    return 2;
  }
  return 1;
}

static const luaL_Reg base_funcs[] = {
  { "print", luaB_print },
  { "error", luaB_error },
  { "tostring", luaB_tostring },
  { "tonumber", luaB_tonumber },
  { "type", luaB_type },
  { "len", luaB_len },
  { "next", luaB_next },
  { "pairs", luaB_pairs },
  { "ipairs", luaB_ipairs },
  { "pcall", luaB_pcall },
  { "xpcall", luaB_xpcall },
  { "select", luaB_select },
  { "rawget", luaB_rawget },
  { "rawset", luaB_rawset },
  { "rawequal", luaB_rawequal },
  { "rawlen", luaB_rawlen },
  { "setmetatable", luaB_setmetatable },
  { "getmetatable", luaB_getmetatable },
  { "assert", luaB_assert },
  { "collectgarbage", luaB_collectgarbage },
  { "dofile", luaB_dofile },
  { "load", luaB_load },
  { NULL, NULL }
};

void luaopen_base (lua_State *L) {
  Table *gt = luaG_globals(L);
  int i;
  for (i = 0; base_funcs[i].name != NULL; i++) {
    TValue v;
    TString *name = luaS_new(L, base_funcs[i].name);
    setclvalue(&v, NULL);
    (void)v;
    /* push the function and set it in the globals table */
    {
      TValue fv;
      Closure *cl = luaF_newCclosure(L, 1);
      cl->f.c = base_funcs[i].fn;
      {
        UpVal *uv = (UpVal *)luaM_new(L, UpVal);
        setnilvalue(&uv->value);
        uv->v = &uv->value;
        uv->chain = NULL;
        luaC_link(L, (GCObject *)uv, LUA_VUPVAL);
        cl->upvals[0] = uv;
      }
      setclvalue(&fv, cl);
      {
        TValue kv;
        setsvalue(&kv, name);
        setobj2t(luaH_set(L, gt, &kv), &fv);
      }
    }
  }
  /* _G */
  {
    TValue kv, gv;
    setsvalue(&kv, *luaS_new(L, "_G") ? & (TValue){ LUA_VNIL, {0} } : NULL);
    (void)kv;
    {
      TValue k2, v2;
      TString *n = luaS_new(L, "_G");
      setsvalue(&k2, n);
      sethvalue(&v2, gt);
      setobj2t(luaH_set(L, gt, &k2), &v2);
    }
    {
      TValue k3, v3;
      TString *n = luaS_new(L, "_VERSION");
      setsvalue(&k3, n);
      setsvalue(&v3, luaS_new(L, LUA_VERSION_));
      setobj2t(luaH_set(L, gt, &k3), &v3);
    }
  }
}
