    return LUA_ERRSYNTAX;
  }
  return LUA_OK;
}

static int dolibrary (lua_State *L) {
  luaopen_base(L);
  return LUA_OK;
}

int main (int argc, char **argv) {
  lua_State *L;
  int status;
  int script = 0;
  int i;
  int interactive = 0;
  int hasE = 0;
  int hasV = 0;
  char **args;
  int nargs = argc;
  int hasi = 0;
  progname = argv[0];
  args = argv;
  /* collect arguments */
  for (i = 1; i < argc; i++) {
    if (argv[i][0] != '-') { script = i; break; }
