      case 'e': i++; break;
      case 'l': i++; break;
      case 'i': hasi = 1; break;
      case 'v': hasV = 1; break;
      case 'E': hasE = 1; break;
      case 'W': break;
      case '-': if (argv[i][1] == '-') { i++; script = i; } goto done;
      default: break;
    }
    if (argv[i][0] != '-') { script = i; break; }
  }
 done:
