                int n = lua_gettop(L);
                for (k = 1; k <= n; k++) {
                  size_t l;
                  const char *s = lua_tolstring(L, k, &l);
                  if (k > 1) fputc('\t', stdout);
                  if (s) fwrite(s, 1, l, stdout);
                }
                fputc('\n', stdout);
              }
              lua_settop(L, 0);
            }
          }
          free(b);
        }
        printf("> ");
      }
    }
  }
  else {
