#include <stdlib.h>

static const char *progname = "lua";

static int report (lua_State *L, int status) {
  if (status != LUA_OK) {
    const char *msg = lua_tostring(L, -1);
    if (msg == NULL) msg = "(error message not a string)";
    fprintf(stderr, "%s: %s\n", progname, msg);
    lua_pop(L, 1);
  }
  return status;
}

static int msghandler (lua_State *L) {
  const char *msg = lua_tostring(L, 1);
  if (msg == NULL) {
    TValue *o = api_index_(L, 1);
    if (o == NULL) msg = "(error object is a nil value)";
    else msg = luaO_pushfstring(L, "(error object is a %s value)", luaO_typename(o));
  }
  {
    /* build the traceback */
    size_t l;
    const char *m = lua_tolstring(L, -1, &l);
    (void)m;
  }
  luaL_traceback(L, L, msg, 1);
  return 1;
}

static int docall (lua_State *L, int narg, int nres) {
  int status;
  int base = lua_gettop(L) - narg;
  lua_pushcfunction(L, msghandler);
  lua_insert(L, base);
  status = lua_pcall(L, narg, nres, base);
  lua_remove(L, base);
  return status;
}

static int loadbuffer (lua_State *L, const char *s, size_t sz, const char *name) {
  TString *src;
  int status;
  src = luaS_new(L, name);
  status = luaY_parser(L, s, sz, src, NULL);
  if (status != LUA_OK) {
    /* the error message is on the stack */
    return LUA_ERRSYNTAX;
  }
  return LUA_OK;
}

static int dolibrary (lua_State *L) {
  luaopen_base(L);
  return LUA_OK;
}

int main (int argc, char **argv) {
  lua_State *L;
  int status;
  int script = 0;
  int i;
  int interactive = 0;
  int hasE = 0;
  int hasV = 0;
  char **args;
  int nargs = argc;
  int hasi = 0;
  progname = argv[0];
  args = argv;
  /* collect arguments */
  for (i = 1; i < argc; i++) {
    if (argv[i][0] != '-') { script = i; break; }
    switch (argv[i][1]) {
      case 'e': i++; break;
      case 'l': i++; break;
      case 'i': hasi = 1; break;
      case 'v': hasV = 1; break;
      case 'E': hasE = 1; break;
      case 'W': break;
      case '-': if (argv[i][1] == '-') { i++; script = i; } goto done;
      default: break;
    }
    if (argv[i][0] != '-') { script = i; break; }
  }
 done:
  if (hasV) printf("%s\n", LUA_COPYRIGHT);
  L = lua_newstate();
  if (L == NULL) { fprintf(stderr, "%s: cannot create state\n", progname); return 1; }
  status = dolibrary(L);
  if (status != LUA_OK) return report(L, status);
  if (script > 0) {
    const char *name = argv[script];
    FILE *fp = (strcmp(name, "-") == 0) ? stdin : fopen(name, "r");
    char *buff;
    size_t sz = 0, cap = 4096;
    int c;
    if (fp == NULL) {
      fprintf(stderr, "%s: cannot open %s: No such file or directory\n", progname, name);
      return 1;
    }
    buff = (char *)malloc(cap);
    while ((c = fgetc(fp)) != EOF) {
      if (sz + 1 >= cap) { cap *= 2; buff = (char *)realloc(buff, cap); }
      buff[sz++] = (char)c;
    }
    if (fp != stdin) fclose(fp);
    {
      TString *src = luaS_new(L, name);
      status = luaY_parser(L, buff, sz, src, NULL);
      if (status != LUA_OK) {
        report(L, status);
        return 1;
      }
      /* create the arg table */
      {
        Table *gt = luaG_globals(L);
        Table *t = luaH_new(L);
        TValue kv, tv;
        int j;
        setsvalue(&kv, luaS_new(L, "arg"));
        sethvalue(&tv, t);
        setobj2t(luaH_set(L, gt, &kv), &tv);
        for (j = 0; j < argc; j++) {
          TValue k, v;
          setivalue(&k, (lua_Integer)(j - script));
          setsvalue(&v, luaS_new(L, argv[j]));
          setobj2t(luaH_setint(L, t, j - script), &v);
        }
      }
      /* run it */
      {
        int nres = 0;
        status = docall(L, 0, LUA_MULTRET);
        if (status != LUA_OK) {
          report(L, status);
          return 1;
        }
        (void)nres;
      }
    }
    free(buff);
  }
  else if (hasi) {
    printf("%s\n", LUA_COPYRIGHT);
    /* minimal interactive mode */
    {
      char line[1024];
      printf("> ");
      while (fgets(line, sizeof(line), stdin) != NULL) {
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') line[len-1] = '\0';
        if (!isatty(0)) printf("%s\n", line);
        {
          char *b;
          size_t bl;
          b = (char *)malloc(strlen(line) + 16);
          sprintf(b, "return %s", line);
          bl = strlen(b);
          {
            int st = loadbuffer(L, b, bl, "stdin");
            if (st != LUA_OK) {
              lua_pop(L, 1);
              b[0] = '\0';
              sprintf(b, "%s", line);
              bl = strlen(b);
              st = loadbuffer(L, b, bl, "stdin");
            }
            if (st != LUA_OK) {
              fprintf(stderr, "%s\n", lua_tostring(L, -1));
              lua_pop(L, 1);
            }
            else {
              int st2 = docall(L, 0, LUA_MULTRET);
              if (st2 != LUA_OK) fprintf(stderr, "%s\n", lua_tostring(L, -1));
              else if (lua_gettop(L) > 0) {
                int k;
                int n = lua_gettop(L);
                for (k = 1; k <= n; k++) {
                  size_t l;
                  const char *s = lua_tolstring(L, k, &l);
                  if (k > 1) fputc('\t', stdout);
                  if (s) fwrite(s, 1, l, stdout);
                }
                fputc('\n', stdout);
              }
              lua_settop(L, 0);
            }
          }
          free(b);
        }
        printf("> ");
      }
    }
  }
  else {
    /* read from stdin */
    char *buff;
    size_t sz = 0, cap = 4096;
    int c;
    buff = (char *)malloc(cap);
    while ((c = fgetc(stdin)) != EOF) {
      if (sz + 1 >= cap) { cap *= 2; buff = (char *)realloc(buff, cap); }
      buff[sz++] = (char)c;
    }
    {
      TString *src = luaS_new(L, "stdin");
      status = luaY_parser(L, buff, sz, src, NULL);
      if (status != LUA_OK) { report(L, status); return 1; }
      status = docall(L, 0, LUA_MULTRET);
      if (status != LUA_OK) { report(L, status); return 1; }
    }
    free(buff);
  }
  lua_close(L);
  return 0;
}
