cat > Makefile <<'C_EOF'
CC = gcc
CFLAGS = -O2 -g -Wall -Wno-unused-parameter -I.
OBJS = lobject.o lmem.o lgc.o lstring.o ltable.o lstate.o lapi.o lfunc.o lvm.o \
       llex.o lparser.o ldebug.o lbaselib.o lua.o

all: ../executable

../executable: $(OBJS)
	$(CC) $(CFLAGS) -o ../executable $(OBJS) -lm

%.o: %.c
	$(CC) $(CFLAGS) -c $< -o $@

clean:
	rm -f $(OBJS) ../executable
